src/pages/Home.tsx.content:
import { Link } from 'react-router-dom';
import { subjects } from '../data/subjects';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, Star, BookOpen, Users } from 'lucide-react';
import { useState, useEffect, useCallback } from 'react';
import SecretHub from '../components/SecretHub';
import { useAuth } from 'zite-auth-sdk';

const SECRET_CODE = 'genizy';

export default function Home() {
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [listening, setListening] = useState(false);
  const [typed, setTyped] = useState('');
  const [hubOpen, setHubOpen] = useState(false);

  const handleBadgeClick = () => {
    setListening(true);
    setTyped('');
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (!listening) return;
    const next = (typed + e.key).slice(-SECRET_CODE.length);
    setTyped(next);
    if (next === SECRET_CODE) {
      setHubOpen(true);
      setListening(false);
      setTyped('');
    }
  }, [listening, typed]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  // Stop listening after 5 seconds of inactivity
  useEffect(() => {
    if (!listening) return;
    const timer = setTimeout(() => { setListening(false); setTyped(''); }, 5000);
    return () => clearTimeout(timer);
  }, [listening, typed]);

  useEffect(() => {
    if (!isLoading && !user) {
      loginWithRedirect({ redirectUrl: window.location.href });
    }
  }, [isLoading, user]);

  if (isLoading || !user) return null;

  return (
    <div>
      <AnimatePresence>
        {hubOpen && <SecretHub onClose={() => setHubOpen(false)} />}
      </AnimatePresence>

      {/* Hero */}
      <section className="relative overflow-hidden bg-gradient-to-br from-primary/10 via-background to-secondary/10 py-20 px-4">
        <div className="container mx-auto text-center max-w-3xl">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
            <div
              onClick={handleBadgeClick}
              className="inline-flex items-center gap-2 bg-primary/10 text-primary rounded-full px-4 py-1 text-sm font-medium mb-6 cursor-default select-none"
            >
              <Star className="w-4 h-4 fill-current" />
              Free Learning for Everyone
            </div>
            <h1 className="text-5xl md:text-6xl font-extrabold text-foreground mb-4 leading-tight">
              Learn Anything,<br />
              <span className="text-primary">Anytime.</span>
            </h1>
            <p className="text-lg text-muted-foreground mb-8 max-w-xl mx-auto">
              Explore interactive lessons across 8 subjects. Build skills, earn confidence, and discover the joy of learning.
            </p>
            <div className="flex justify-center gap-8 mb-2">
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">8</div>
                <div className="text-sm text-muted-foreground">Subjects</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">32+</div>
                <div className="text-sm text-muted-foreground">Lessons</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">100%</div>
                <div className="text-sm text-muted-foreground">Free</div>
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Subjects Grid */}
      <section className="container mx-auto px-4 py-16">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-foreground mb-2">Choose a Subject</h2>
          <p className="text-muted-foreground">Click any subject to start learning</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {subjects.map((subject, i) => (
            <motion.div
              key={subject.id}
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.07 }}
            >
              <Link to={`/subject/${subject.id}`}>
                <div className={`group rounded-2xl border-2 ${subject.borderColor} ${subject.bgColor} p-6 h-full hover:shadow-lg transition-all duration-200 hover:-translate-y-1 cursor-pointer`}>
                  <div className="text-5xl mb-4">{subject.emoji}</div>
                  <h3 className={`text-xl font-bold mb-1 ${subject.color}`}>{subject.name}</h3>
                  <p className="text-sm text-muted-foreground mb-4 leading-relaxed">{subject.tagline}</p>
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-muted-foreground flex items-center gap-1">
                      <BookOpen className="w-3 h-3" />
                      {subject.lessons.length} lessons
                    </span>
                    <ChevronRight className={`w-4 h-4 ${subject.color} group-hover:translate-x-1 transition-transform`} />
                  </div>
                </div>
              </Link>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Footer Banner */}
      <section className="bg-primary/5 border-t border-border py-12 px-4 mt-8">
        <div className="container mx-auto flex flex-col md:flex-row items-center justify-between gap-4 max-w-4xl">
          <div className="flex items-center gap-3">
            <Users className="w-8 h-8 text-primary" />
            <div>
              <div className="font-semibold text-foreground">Built for Curious Learners</div>
              <div className="text-sm text-muted-foreground">From elementary to high school — all levels welcome</div>
            </div>
          </div>
          <div className="text-sm text-muted-foreground text-center md:text-right">
            EduWorld • Free Educational Resources
          </div>
        </div>
      </section>
    </div>
  );
}

