import { z } from 'zod';
import { createEndpoint, SiteSettings, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Update a site setting - admin only',
  authenticated: true,
  inputSchema: z.object({
    key: z.string(),
    value: z.string(),
    description: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    const existing = await SiteSettings.findOne({ filters: { settingKey: input.key } });
    if (existing) {
      await SiteSettings.update({ id: existing.id, record: { settingValue: input.value } });
    } else {
      await SiteSettings.create({
        record: { settingKey: input.key, settingValue: input.value, description: input.description ?? '' },
      });
    }
    return { success: true };
  },
});

