import { z } from 'zod';
import { createEndpoint, Announcements, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create, update, or delete an announcement - admin only',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['create', 'update', 'delete']),
    id: z.string().optional(),
    title: z.string().optional(),
    message: z.string().optional(),
    status: z.enum(['Active', 'Draft', 'Archived']).optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string().optional() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    if (input.action === 'create') {
      const record = await Announcements.create({
        record: {
          title: input.title,
          message: input.message,
          status: input.status ?? 'Draft',
          postedAt: new Date().toISOString(),
          postedBy: context.user.email,
        },
      });
      return { success: true, id: record.id };
    }
    if (input.action === 'update' && input.id) {
      await Announcements.update({
        id: input.id,
        record: { title: input.title, message: input.message, status: input.status },
      });
      return { success: true, id: input.id };
    }
    if (input.action === 'delete' && input.id) {
      await Announcements.delete({ id: input.id });
      return { success: true };
    }
    throw new ZiteError({ code: 'BAD_REQUEST', message: 'Invalid action' });
  },
});

src/components/IframeViewer.tsx.content:
import { useState, useRef } from 'react';
import { motion } from 'framer-motion';
import { X, Maximize2, Minimize2, ExternalLink, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface Props {
  url: string;
  title: string;
  emoji?: string;
  onClose: () => void;
}

export function openCloaked(url: string, title: string) {
  const w = window.open('about:blank', '_blank');
  if (!w) return;
  w.document.write(`<!DOCTYPE html><html><head><title>${title}</title><style>*{margin:0;padding:0;box-sizing:border-box}html,body,iframe{width:100%;height:100%;border:none;overflow:hidden}</style></head><body><iframe src="${url}" allowfullscreen allow="autoplay; fullscreen"></iframe></body></html>`);
  w.document.close();
}

export default function IframeViewer({ url, title, emoji, onClose }: Props) {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const toggleFullscreen = () => {
    if (!isFullscreen) {
      containerRef.current?.requestFullscreen?.().catch(() => {});
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
    setIsFullscreen(!isFullscreen);
  };

  return (
    <motion.div
      ref={containerRef}
      initial={{ opacity: 0, scale: 0.97 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.97 }}
      className="fixed inset-0 z-[10000] bg-black flex flex-col"
    >
      {/* Toolbar */}
      <div className="flex items-center gap-2 px-3 py-2 bg-card border-b border-border shrink-0">
        <button onClick={onClose} className="flex items-center gap-1.5 text-muted-foreground hover:text-foreground transition-colors text-sm">
          <ArrowLeft className="w-4 h-4" /> Back
        </button>
        <div className="flex-1 flex items-center justify-center gap-2">
          {emoji && <span>{emoji}</span>}
          <span className="text-sm font-medium text-foreground truncate max-w-xs">{title}</span>
        </div>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7 text-muted-foreground hover:text-foreground"
            title="Open cloaked in new tab"
            onClick={() => openCloaked(url, title)}
          >
            <ExternalLink className="w-4 h-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7 text-muted-foreground hover:text-foreground"
            title={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
            onClick={toggleFullscreen}
          >
            {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-foreground" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>
      {/* Iframe */}
      <iframe
        src={url}
        className="flex-1 w-full border-none"
        allow="autoplay; fullscreen; accelerometer; gyroscope"
        allowFullScreen
        title={title}
      />
    </motion.div>
  );
}

