import { useState, useEffect } from 'react';
import { getHubTabs, manageHubTab, manageHubItem, GetHubTabsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Plus, Trash2, Pencil, ChevronRight, ArrowLeft, Check, Layers, Link } from 'lucide-react';
import { toast } from 'sonner';
import { motion, AnimatePresence } from 'framer-motion';

type HubTab = GetHubTabsOutputType['tabs'][0];
type HubItem = HubTab['items'][0];

type View = 'tabs' | 'items' | 'editTab' | 'editItem';

export default function TabManager() {
  const [tabs, setTabs] = useState<HubTab[]>([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<View>('tabs');
  const [selectedTab, setSelectedTab] = useState<HubTab | null>(null);
  const [editingTab, setEditingTab] = useState<Partial<HubTab> | null>(null);
  const [editingItem, setEditingItem] = useState<Partial<HubItem & { tabId?: string }> | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ type: 'tab' | 'item'; id: string; name: string } | null>(null);
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getHubTabs({});
      setTabs(res.tabs);
      if (selectedTab) {
        const updated = res.tabs.find(t => t.id === selectedTab.id);
        if (updated) setSelectedTab(updated);
      }
    } catch { toast.error('Failed to load tabs'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  // Save tab
  const saveTab = async () => {
    if (!editingTab?.tabName?.trim()) { toast.error('Tab name required'); return; }
    setSaving(true);
    try {
      if (editingTab.id) {
        await manageHubTab({ action: 'update', id: editingTab.id, tabName: editingTab.tabName, emoji: editingTab.emoji ?? '', tabType: (editingTab.tabType as 'Single' | 'Multiple') ?? 'Multiple', sortOrder: editingTab.sortOrder ?? 0 });
        toast.success('Tab updated');
      } else {
        await manageHubTab({ action: 'create', tabName: editingTab.tabName, emoji: editingTab.emoji ?? '', tabType: (editingTab.tabType as 'Single' | 'Multiple') ?? 'Multiple', sortOrder: editingTab.sortOrder ?? 0 });
        toast.success('Tab created');
      }
      await load();
      setView('tabs');
      setEditingTab(null);
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSaving(false);
  };

  // Save item
  const saveItem = async () => {
    if (!editingItem?.itemName?.trim()) { toast.error('Item name required'); return; }
    if (!editingItem?.url?.trim()) { toast.error('URL required'); return; }
    setSaving(true);
    try {
      if (editingItem.id) {
        await manageHubItem({ action: 'update', id: editingItem.id, itemName: editingItem.itemName, url: editingItem.url, emoji: editingItem.emoji ?? '', description: editingItem.description ?? '' });
        toast.success('Item updated');
      } else {
        await manageHubItem({ action: 'create', tabId: selectedTab?.id, itemName: editingItem.itemName, url: editingItem.url, emoji: editingItem.emoji ?? '', description: editingItem.description ?? '' });
        toast.success('Item added');
      }
      await load();
      setView('items');
      setEditingItem(null);
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSaving(false);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      if (deleteTarget.type === 'tab') {
        await manageHubTab({ action: 'delete', id: deleteTarget.id });
        setSelectedTab(null);
        setView('tabs');
        toast.success('Tab deleted');
      } else {
        await manageHubItem({ action: 'delete', id: deleteTarget.id });
        toast.success('Item deleted');
      }
      await load();
    } catch (e: any) { toast.error(e?.message ?? 'Failed to delete'); }
    setDeleteTarget(null);
  };

  const renderTabList = () => (
    <div className="space-y-3">
      <div className="flex justify-between items-center">
        <span className="text-sm text-muted-foreground">{tabs.length} custom tab{tabs.length !== 1 ? 's' : ''}</span>
        <Button size="sm" onClick={() => { setEditingTab({ tabType: 'Multiple', sortOrder: tabs.length }); setView('editTab'); }}>
          <Plus className="w-4 h-4 mr-1" /> New Tab
        </Button>
      </div>
      {loading ? (
        <div className="space-y-2">{[...Array(3)].map((_, i) => <div key={i} className="h-14 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : tabs.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No custom tabs yet. Create one to get started.</div>
      ) : (
        <div className="space-y-2 max-h-80 overflow-y-auto pr-1">
          {tabs.map(tab => (
            <div key={tab.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3 group">
              <span className="text-xl">{tab.emoji || '📋'}</span>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground">{tab.tabName}</div>
                <div className="text-xs text-muted-foreground">{tab.tabType} · {tab.items?.length ?? 0} item{(tab.items?.length ?? 0) !== 1 ? 's' : ''}</div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <Button variant="ghost" size="sm" className="h-7 text-xs gap-1" onClick={() => { setSelectedTab(tab); setView('items'); }}>
                  Items <ChevronRight className="w-3 h-3" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setEditingTab(tab); setView('editTab'); }}>
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget({ type: 'tab', id: tab.id, name: tab.tabName ?? '' })}>
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderItemList = () => (
    <div className="space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <Button variant="ghost" size="sm" onClick={() => setView('tabs')}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{selectedTab?.emoji} {selectedTab?.tabName}</span>
        <span className="text-xs text-muted-foreground px-2 py-0.5 rounded-full bg-muted border border-border">{selectedTab?.tabType}</span>
      </div>
      <div className="flex justify-end">
        <Button size="sm" onClick={() => { setEditingItem({}); setView('editItem'); }}>
          <Plus className="w-4 h-4 mr-1" /> Add Item
        </Button>
      </div>
      {(selectedTab?.items?.length ?? 0) === 0 ? (
        <div className="text-center py-8 text-muted-foreground text-sm">No items yet</div>
      ) : (
        <div className="space-y-2 max-h-72 overflow-y-auto pr-1">
          {selectedTab?.items?.map(item => (
            <div key={item.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3">
              <span className="text-lg">{item.emoji || '🔗'}</span>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground">{item.itemName}</div>
                <div className="text-xs text-muted-foreground truncate">{item.url}</div>
              </div>
              <div className="flex gap-1 shrink-0">
                <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setEditingItem(item); setView('editItem'); }}>
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget({ type: 'item', id: item.id, name: item.itemName ?? '' })}>
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderEditTab = () => (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={() => { setView('tabs'); setEditingTab(null); }}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{editingTab?.id ? 'Edit Tab' : 'New Tab'}</span>
      </div>
      <div className="grid grid-cols-4 gap-2">
        <Input placeholder="Emoji" value={editingTab?.emoji ?? ''} onChange={e => setEditingTab(p => ({ ...p, emoji: e.target.value }))} className="col-span-1" />
        <Input placeholder="Tab name" value={editingTab?.tabName ?? ''} onChange={e => setEditingTab(p => ({ ...p, tabName: e.target.value }))} className="col-span-3" />
      </div>
      <div className="space-y-1">
        <label className="text-xs text-muted-foreground font-medium">Tab Type</label>
        <Select value={editingTab?.tabType ?? 'Multiple'} onValueChange={v => setEditingTab(p => ({ ...p, tabType: v }))}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="Multiple">Multiple Items — grid layout</SelectItem>
            <SelectItem value="Single">Single Item — direct launch</SelectItem>
          </SelectContent>
        </Select>
        <p className="text-xs text-muted-foreground pt-1">
          {editingTab?.tabType === 'Single'
            ? 'Only the first item is used. It opens directly with iframe/fullscreen/cloaked options.'
            : 'All items shown as a gaming-style grid. Each card has its own launch options.'}
        </p>
      </div>
      <Input placeholder="Sort order (0 = first)" type="number" value={editingTab?.sortOrder ?? 0} onChange={e => setEditingTab(p => ({ ...p, sortOrder: Number(e.target.value) }))} />
      <div className="flex gap-2">
        <Button onClick={saveTab} disabled={saving}><Check className="w-4 h-4 mr-1" />{saving ? 'Saving...' : 'Save Tab'}</Button>
        <Button variant="outline" onClick={() => { setView('tabs'); setEditingTab(null); }}>Cancel</Button>
      </div>
    </div>
  );

  const renderEditItem = () => (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={() => { setView('items'); setEditingItem(null); }}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{editingItem?.id ? 'Edit Item' : 'New Item'}</span>
      </div>
      <div className="grid grid-cols-4 gap-2">
        <Input placeholder="Emoji" value={editingItem?.emoji ?? ''} onChange={e => setEditingItem(p => ({ ...p, emoji: e.target.value }))} className="col-span-1" />
        <Input placeholder="Item name" value={editingItem?.itemName ?? ''} onChange={e => setEditingItem(p => ({ ...p, itemName: e.target.value }))} className="col-span-3" />
      </div>
      <div className="relative">
        <Link className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
        <Input placeholder="https://example.com" value={editingItem?.url ?? ''} onChange={e => setEditingItem(p => ({ ...p, url: e.target.value }))} className="pl-8" />
      </div>
      <Input placeholder="Short description (optional)" value={editingItem?.description ?? ''} onChange={e => setEditingItem(p => ({ ...p, description: e.target.value }))} />
      <div className="flex gap-2">
        <Button onClick={saveItem} disabled={saving}><Check className="w-4 h-4 mr-1" />{saving ? 'Saving...' : 'Save Item'}</Button>
        <Button variant="outline" onClick={() => { setView('items'); setEditingItem(null); }}>Cancel</Button>
      </div>
    </div>
  );

  return (
    <div>
      <div className="flex items-center gap-2 mb-4">
        <Layers className="w-4 h-4 text-primary" />
        <span className="text-sm font-medium text-foreground">Custom Hub Tabs</span>
        <span className="text-xs text-muted-foreground">— visible to all hub visitors</span>
      </div>
      <AnimatePresence mode="wait">
        <motion.div key={view} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -8 }} transition={{ duration: 0.12 }}>
          {view === 'tabs' && renderTabList()}
          {view === 'items' && renderItemList()}
          {view === 'editTab' && renderEditTab()}
          {view === 'editItem' && renderEditItem()}
        </motion.div>
      </AnimatePresence>

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteTarget?.type === 'tab' ? 'Tab' : 'Item'}</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete "<strong>{deleteTarget?.name}</strong>"?
              {deleteTarget?.type === 'tab' && ' All items in this tab will also be deleted.'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

src/components/admin/UserManager.tsx.content:
import { useState, useEffect, useCallback } from 'react';
import { getUsers, getUserStats, bulkUpdateUsers, updateUser, deleteUser, GetUsersOutputType, GetUserStatsOutputType } from 'zite-endpoints-sdk';
import { useDebouncedCallback } from 'use-debounce';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Crown, Shield, ShieldCheck, User, UserX, Trash2, RefreshCw, Search, ArrowUpDown, ArrowUp, ArrowDown, ChevronLeft, ChevronRight, Pencil, Ban, UserCheck, Users, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import UserDetailModal from './UserDetailModal';

type UserRow = GetUsersOutputType['users'][0];
type RoleName = 'Owner' | 'Admin' | 'Moderator' | 'User' | 'Banned';

const PAGE_SIZE = 20;

const ROLE_META: Record<string, { color: string; icon: React.ReactNode }> = {
  Owner:     { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', icon: <Crown className="w-3 h-3" /> },
  Admin:     { color: 'bg-primary/20 text-primary border-primary/30', icon: <Shield className="w-3 h-3" /> },
  Moderator: { color: 'bg-purple-500/20 text-purple-400 border-purple-500/30', icon: <ShieldCheck className="w-3 h-3" /> },
  User:      { color: 'bg-muted text-muted-foreground border-border', icon: <User className="w-3 h-3" /> },
  Banned:    { color: 'bg-destructive/20 text-destructive border-destructive/30', icon: <UserX className="w-3 h-3" /> },
};

function roleRank(r?: string) {
  return r === 'Owner' ? 4 : r === 'Admin' ? 3 : r === 'Moderator' ? 2 : r === 'Banned' ? 0 : 1;
}

function timeAgo(iso?: string) {
  if (!iso) return '—';
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  if (d < 30) return `${d}d ago`;
  return new Date(iso).toLocaleDateString();
}

// ── Stat Card ──────────────────────────────────────────────────────────────
function StatCard({ label, value, icon, accent }: { label: string; value: number; icon: React.ReactNode; accent: string }) {
  return (
    <div className="bg-muted/30 border border-border rounded-xl px-4 py-3 flex flex-col gap-1.5">
      <div className={`flex items-center gap-1.5 text-xs font-medium ${accent}`}>{icon} {label}</div>
      <div className="text-2xl font-bold text-foreground">{value}</div>
    </div>
  );
}

// ── Bulk Action Bar ─────────────────────────────────────────────────────────
interface BulkBarProps {
  count: number;
  myRole?: string;
  loading: boolean;
  onClear: () => void;
  onBulkAction: (action: string) => void;
}
function BulkActionBar({ count, myRole, loading, onClear, onBulkAction }: BulkBarProps) {
  const [bulkRole, setBulkRole] = useState('');
  const canDelete = roleRank(myRole) >= 3;
  const roles = myRole === 'Owner' ? ['Admin','Moderator','User','Banned'] : myRole === 'Admin' ? ['Moderator','User','Banned'] : ['User','Banned'];

  return (
    <div className="flex flex-wrap items-center gap-2 bg-primary/10 border border-primary/30 rounded-xl px-4 py-2.5">
      <span className="text-sm font-semibold text-primary">{count} selected</span>
      <div className="flex items-center gap-1.5 flex-wrap">
        <Select value={bulkRole} onValueChange={setBulkRole}>
          <SelectTrigger className="h-7 w-32 text-xs"><SelectValue placeholder="Change role…" /></SelectTrigger>
          <SelectContent>{roles.map(r => <SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent>
        </Select>
        {bulkRole && (
          <Button size="sm" className="h-7 text-xs" disabled={loading} onClick={() => { onBulkAction(`role:${bulkRole}`); setBulkRole(''); }}>
            Apply Role
          </Button>
        )}
        <Button size="sm" variant="outline" className="h-7 text-xs" disabled={loading} onClick={() => onBulkAction('activate')}>
          <UserCheck className="w-3 h-3 mr-1" />Activate
        </Button>
        <Button size="sm" variant="outline" className="h-7 text-xs" disabled={loading} onClick={() => onBulkAction('deactivate')}>
          <Ban className="w-3 h-3 mr-1" />Deactivate
        </Button>
        <Button size="sm" variant="outline" className="h-7 text-xs" disabled={loading} onClick={() => onBulkAction('ban')}>
          <UserX className="w-3 h-3 mr-1" />Ban All
        </Button>
        {canDelete && (
          <Button size="sm" variant="destructive" className="h-7 text-xs" disabled={loading} onClick={() => onBulkAction('delete')}>
            <Trash2 className="w-3 h-3 mr-1" />Delete
          </Button>
        )}
      </div>
      <Button variant="ghost" size="sm" className="h-7 text-xs ml-auto" onClick={onClear}>Clear</Button>
    </div>
  );
}

// ── User Row ────────────────────────────────────────────────────────────────
interface RowProps {
  user: UserRow;
  myRole?: string;
  selected: boolean;
  onSelect: (id: string, checked: boolean) => void;
  onEdit: (user: UserRow) => void;
  onRoleChange: (userId: string, role: RoleName) => void;
  onToggleActive: (user: UserRow) => void;
  onDelete: (user: UserRow) => void;
  updating: boolean;
}
function UserRow({ user, myRole, selected, onSelect, onEdit, onRoleChange, onToggleActive, onDelete, updating }: RowProps) {
  const meta = ROLE_META[user.role ?? 'User'] ?? ROLE_META.User;
  const myRank = roleRank(myRole);
  const targetRank = roleRank(user.role);
  const canModify = targetRank < myRank;
  const canDelete = myRank >= 3 && canModify;
  const assignableRoles = myRole === 'Owner' ? ['Owner','Admin','Moderator','User','Banned']
    : myRole === 'Admin' ? ['Moderator','User','Banned']
    : myRole === 'Moderator' ? ['User','Banned'] : [];
  const initials = user.firstName
    ? (user.firstName[0] + (user.lastName?.[0] ?? '')).toUpperCase()
    : (user.email?.[0] ?? '?').toUpperCase();

  return (
    <div className={`flex items-center gap-3 border rounded-xl px-4 py-3 transition-colors ${selected ? 'bg-primary/5 border-primary/30' : 'bg-muted/20 border-border hover:bg-muted/40'}`}>
      <Checkbox checked={selected} onCheckedChange={c => onSelect(user.id, !!c)} disabled={!canModify} className="shrink-0" />
      <button onClick={() => onEdit(user)} className="w-9 h-9 rounded-full bg-primary/15 flex items-center justify-center text-sm font-bold text-primary shrink-0 hover:bg-primary/25 transition-colors">
        {initials}
      </button>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="font-medium text-sm text-foreground">
            {user.firstName || user.lastName ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() : user.email}
          </span>
          <span className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full border font-medium ${meta.color}`}>
            {meta.icon} {user.role ?? 'User'}
          </span>
          {user.isActive === false && (
            <span className="text-xs px-2 py-0.5 rounded-full bg-destructive/10 text-destructive border border-destructive/20 font-medium">
              Inactive
            </span>
          )}
        </div>
        <div className="flex items-center gap-3 mt-0.5">
          {user.firstName && <span className="text-xs text-muted-foreground truncate max-w-[160px]">{user.email}</span>}
          {user.lastActive && <span className="text-xs text-muted-foreground hidden sm:block">{timeAgo(user.lastActive)}</span>}
          {user.joinedAt && <span className="text-xs text-muted-foreground hidden md:block">Joined {new Date(user.joinedAt).toLocaleDateString()}</span>}
        </div>
      </div>
      {canModify && (
        <div className="flex items-center gap-1 shrink-0">
          {assignableRoles.length > 0 && (
            <Select value={user.role ?? 'User'} onValueChange={v => onRoleChange(user.id, v as RoleName)} disabled={updating}>
              <SelectTrigger className="h-7 w-28 text-xs"><SelectValue /></SelectTrigger>
              <SelectContent>{assignableRoles.map(r => <SelectItem key={r} value={r}>{r}</SelectItem>)}</SelectContent>
            </Select>
          )}
          <Button variant="ghost" size="icon" className="h-7 w-7" title="Edit user" onClick={() => onEdit(user)} disabled={updating}>
            <Pencil className="w-3.5 h-3.5" />
          </Button>
          <Button variant="ghost" size="icon" className="h-7 w-7" title={user.isActive !== false ? 'Deactivate' : 'Activate'} onClick={() => onToggleActive(user)} disabled={updating}>
            {user.isActive !== false ? <Ban className="w-3.5 h-3.5 text-muted-foreground" /> : <UserCheck className="w-3.5 h-3.5 text-primary" />}
          </Button>
          {canDelete && (
            <Button variant="ghost" size="icon" className="h-7 w-7" title="Delete user" onClick={() => onDelete(user)} disabled={updating}>
              <Trash2 className="w-3.5 h-3.5 text-muted-foreground hover:text-destructive" />
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

// ── Main Component ──────────────────────────────────────────────────────────
export default function UserManager({ myRole }: { myRole?: string }) {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [stats, setStats] = useState<GetUserStatsOutputType | null>(null);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [statsLoading, setStatsLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [sortBy, setSortBy] = useState<string>('joinedAt');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');
  const [offset, setOffset] = useState(0);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [updating, setUpdating] = useState<string | null>(null);
  const [bulkLoading, setBulkLoading] = useState(false);
  const [editTarget, setEditTarget] = useState<UserRow | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<UserRow | null>(null);

  const loadStats = async () => {
    setStatsLoading(true);
    try { setStats(await getUserStats({})); } catch { /* ignore */ }
    setStatsLoading(false);
  };

  const loadUsers = useCallback(async (s = search, rf = roleFilter, sb = sortBy, sd = sortDir, off = offset) => {
    setLoading(true);
    try {
      const res = await getUsers({ search: s, roleFilter: rf, sortBy: sb as any, sortDir: sd, offset: off, limit: PAGE_SIZE });
      setUsers(res.users);
      setTotal(res.total);
    } catch { toast.error('Failed to load users'); }
    setLoading(false);
  }, [search, roleFilter, sortBy, sortDir, offset]);

  useEffect(() => { loadStats(); }, []);
  useEffect(() => { loadUsers(); }, []);

  const debouncedSearch = useDebouncedCallback((val: string) => {
    setOffset(0);
    loadUsers(val, roleFilter, sortBy, sortDir, 0);
  }, 350);

  const handleSearch = (val: string) => { setSearch(val); debouncedSearch(val); };

  const handleFilter = (val: string) => { setRoleFilter(val); setOffset(0); loadUsers(search, val, sortBy, sortDir, 0); };

  const handleSort = (col: string) => {
    const dir = sortBy === col && sortDir === 'desc' ? 'asc' : 'desc';
    setSortBy(col); setSortDir(dir); setOffset(0);
    loadUsers(search, roleFilter, col, dir, 0);
  };

  const handlePage = (dir: 1 | -1) => {
    const next = Math.max(0, offset + dir * PAGE_SIZE);
    setOffset(next);
    loadUsers(search, roleFilter, sortBy, sortDir, next);
  };

  const handleRoleChange = async (userId: string, role: RoleName) => {
    setUpdating(userId);
    try {
      await updateUser({ userId, role });
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, role } : u));
      await loadStats();
      toast.success('Role updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setUpdating(null);
  };

  const handleToggleActive = async (user: UserRow) => {
    setUpdating(user.id);
    try {
      await updateUser({ userId: user.id, isActive: !user.isActive });
      setUsers(prev => prev.map(u => u.id === user.id ? { ...u, isActive: !u.isActive } : u));
      await loadStats();
      toast.success('Status updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setUpdating(null);
  };

  const handleDeleteConfirm = async () => {
    if (!deleteTarget) return;
    try {
      await deleteUser({ userId: deleteTarget.id });
      setUsers(prev => prev.filter(u => u.id !== deleteTarget.id));
      setSelected(prev => { const n = new Set(prev); n.delete(deleteTarget.id); return n; });
      setTotal(t => t - 1);
      await loadStats();
      toast.success('User deleted');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setDeleteTarget(null);
  };

  const handleSelect = (id: string, checked: boolean) => {
    setSelected(prev => { const n = new Set(prev); checked ? n.add(id) : n.delete(id); return n; });
  };

  const handleSelectAll = (checked: boolean) => {
    if (checked) setSelected(new Set(users.filter(u => roleRank(u.role) < roleRank(myRole)).map(u => u.id)));
    else setSelected(new Set());
  };

  const handleBulkAction = async (action: string) => {
    const ids = Array.from(selected);
    if (!ids.length) return;
    setBulkLoading(true);
    try {
      if (action === 'delete') {
        for (const id of ids) await deleteUser({ userId: id });
        setUsers(prev => prev.filter(u => !selected.has(u.id)));
        setTotal(t => t - ids.length);
        toast.success(`Deleted ${ids.length} users`);
      } else if (action.startsWith('role:')) {
        const role = action.split(':')[1] as RoleName;
        await bulkUpdateUsers({ userIds: ids, role });
        setUsers(prev => prev.map(u => selected.has(u.id) ? { ...u, role } : u));
        toast.success(`Changed ${ids.length} users to ${role}`);
      } else if (action === 'activate') {
        await bulkUpdateUsers({ userIds: ids, isActive: true });
        setUsers(prev => prev.map(u => selected.has(u.id) ? { ...u, isActive: true } : u));
        toast.success(`Activated ${ids.length} users`);
      } else if (action === 'deactivate') {
        await bulkUpdateUsers({ userIds: ids, isActive: false });
        setUsers(prev => prev.map(u => selected.has(u.id) ? { ...u, isActive: false } : u));
        toast.success(`Deactivated ${ids.length} users`);
      } else if (action === 'ban') {
        await bulkUpdateUsers({ userIds: ids, role: 'Banned' });
        setUsers(prev => prev.map(u => selected.has(u.id) ? { ...u, role: 'Banned' } : u));
        toast.success(`Banned ${ids.length} users`);
      }
      setSelected(new Set());
      await loadStats();
    } catch (e: any) { toast.error(e?.message ?? 'Bulk action failed'); }
    setBulkLoading(false);
  };

  const handleUpdateFromModal = (updated: UserRow) => {
    setUsers(prev => prev.map(u => u.id === updated.id ? updated : u));
    if (editTarget?.id === updated.id) setEditTarget(updated);
    loadStats();
  };

  const handleDeleteFromModal = (userId: string) => {
    setUsers(prev => prev.filter(u => u.id !== userId));
    setTotal(t => t - 1);
    setSelected(prev => { const n = new Set(prev); n.delete(userId); return n; });
    loadStats();
  };

  const SortIcon = ({ col }: { col: string }) => (
    sortBy === col
      ? sortDir === 'desc' ? <ArrowDown className="w-3 h-3 ml-1" /> : <ArrowUp className="w-3 h-3 ml-1" />
      : <ArrowUpDown className="w-3 h-3 ml-1 opacity-30" />
  );

  const currentPage = Math.floor(offset / PAGE_SIZE) + 1;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const allPageSelectable = users.filter(u => roleRank(u.role) < roleRank(myRole));
  const allSelected = allPageSelectable.length > 0 && allPageSelectable.every(u => selected.has(u.id));

  return (
    <div className="space-y-4">
      {/* Permission hint */}
      <div className="flex items-center gap-2 text-xs text-muted-foreground bg-muted/30 rounded-lg px-3 py-2 border border-border">
        {myRole === 'Owner' && <><Crown className="w-3.5 h-3.5 text-yellow-400" /> Owner — full user management including admins</>}
        {myRole === 'Admin' && <><Shield className="w-3.5 h-3.5 text-primary" /> Admin — manage Moderators and below, edit names</>}
        {myRole === 'Moderator' && <><ShieldCheck className="w-3.5 h-3.5 text-purple-400" /> Moderator — can ban/unban regular users only</>}
      </div>

      {/* Stats */}
      {statsLoading ? (
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
          {[...Array(5)].map((_, i) => <div key={i} className="h-16 rounded-xl bg-muted/40 animate-pulse" />)}
        </div>
      ) : stats && (
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
          <StatCard label="Total" value={stats.total} icon={<Users className="w-3 h-3" />} accent="text-foreground" />
          <StatCard label="Active" value={stats.active} icon={<UserCheck className="w-3 h-3" />} accent="text-emerald-500" />
          <StatCard label="Admins" value={stats.byRole.Admin} icon={<Shield className="w-3 h-3" />} accent="text-primary" />
          <StatCard label="Mods" value={stats.byRole.Moderator} icon={<ShieldCheck className="w-3 h-3" />} accent="text-purple-400" />
          <StatCard label="Banned" value={stats.byRole.Banned} icon={<UserX className="w-3 h-3" />} accent="text-destructive" />
        </div>
      )}

      {/* Controls */}
      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search by name or email…" className="pl-9" value={search} onChange={e => handleSearch(e.target.value)} />
        </div>
        <Select value={roleFilter} onValueChange={handleFilter}>
          <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Roles</SelectItem>
            <SelectItem value="Owner">Owner</SelectItem>
            <SelectItem value="Admin">Admin</SelectItem>
            <SelectItem value="Moderator">Moderator</SelectItem>
            <SelectItem value="User">User</SelectItem>
            <SelectItem value="Banned">Banned</SelectItem>
          </SelectContent>
        </Select>
        <div className="flex gap-1">
          {[['email','Email'],['role','Role'],['joinedAt','Joined'],['lastActive','Active']].map(([col, label]) => (
            <Button key={col} variant={sortBy === col ? 'secondary' : 'outline'} size="sm" className="h-9 text-xs px-2.5" onClick={() => handleSort(col)}>
              {label}<SortIcon col={col} />
            </Button>
          ))}
        </div>
        <Button variant="outline" size="icon" onClick={() => { loadUsers(); loadStats(); }}>
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {/* Summary & select all */}
      <div className="flex items-center justify-between text-xs text-muted-foreground px-1">
        <span>{total} user{total !== 1 ? 's' : ''}{search || roleFilter !== 'all' ? ' (filtered)' : ''}</span>
        <label className="flex items-center gap-1.5 cursor-pointer">
          <Checkbox checked={allSelected} onCheckedChange={c => handleSelectAll(!!c)} />
          Select all on page
        </label>
      </div>

      {/* Bulk action bar */}
      {selected.size > 0 && (
        <BulkActionBar
          count={selected.size}
          myRole={myRole}
          loading={bulkLoading}
          onClear={() => setSelected(new Set())}
          onBulkAction={handleBulkAction}
        />
      )}

      {/* User list */}
      {loading ? (
        <div className="space-y-2">{[...Array(5)].map((_, i) => <div key={i} className="h-16 rounded-xl bg-muted/40 animate-pulse" />)}</div>
      ) : users.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground text-sm">
          <Users className="w-10 h-10 mx-auto mb-3 opacity-30" />
          No users found
        </div>
      ) : (
        <div className="space-y-2">
          {users.map(user => (
            <UserRow
              key={user.id}
              user={user}
              myRole={myRole}
              selected={selected.has(user.id)}
              onSelect={handleSelect}
              onEdit={setEditTarget}
              onRoleChange={handleRoleChange}
              onToggleActive={handleToggleActive}
              onDelete={setDeleteTarget}
              updating={updating === user.id || bulkLoading}
            />
          ))}
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between pt-2">
          <Button variant="outline" size="sm" onClick={() => handlePage(-1)} disabled={offset === 0 || loading}>
            <ChevronLeft className="w-4 h-4 mr-1" />Previous
          </Button>
          <span className="text-sm text-muted-foreground">Page {currentPage} of {totalPages}</span>
          <Button variant="outline" size="sm" onClick={() => handlePage(1)} disabled={offset + PAGE_SIZE >= total || loading}>
            Next<ChevronRight className="w-4 h-4 ml-1" />
          </Button>
        </div>
      )}

      {/* User detail modal */}
      {editTarget && (
        <UserDetailModal
          user={editTarget}
          myRole={myRole}
          onClose={() => setEditTarget(null)}
          onUpdate={handleUpdateFromModal}
          onDelete={handleDeleteFromModal}
        />
      )}

      {/* Delete confirm */}
      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5 text-destructive" />Delete User
            </AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete <strong>{deleteTarget?.email}</strong>? This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteConfirm} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

