import { useState, useEffect } from 'react';
import { getAuditLog, GetAuditLogOutputType } from 'zite-endpoints-sdk';
import { RefreshCw, Crown, Shield, ShieldCheck, ClipboardList } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';

type Entry = GetAuditLogOutputType['entries'][0];

const ROLE_ICON: Record<string, React.ReactNode> = {
  Owner: <Crown className="w-3 h-3 text-yellow-400" />,
  Admin: <Shield className="w-3 h-3 text-primary" />,
  Moderator: <ShieldCheck className="w-3 h-3 text-purple-400" />,
};

function formatDate(iso?: string) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString();
}

export default function AuditLogViewer() {
  const [entries, setEntries] = useState<Entry[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try { const res = await getAuditLog({ limit: 100 }); setEntries(res.entries); }
    catch { toast.error('Failed to load audit log'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <ClipboardList className="w-4 h-4" /> {entries.length} log entries
        </div>
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={load}>
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">{[...Array(5)].map((_, i) => <div key={i} className="h-12 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : entries.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No audit log entries yet</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {entries.map(entry => (
            <div key={entry.id} className="bg-muted/30 border border-border rounded-lg px-4 py-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-0.5">
                    <span className="flex items-center gap-1 text-xs font-medium text-foreground">
                      {ROLE_ICON[entry.roleLevel ?? ''] ?? null}
                      {entry.performedBy}
                    </span>
                    <span className="text-xs text-muted-foreground">→</span>
                    <span className="text-xs text-foreground/70">{entry.targetUser}</span>
                  </div>
                  <div className="text-xs font-semibold text-primary">{entry.action}</div>
                  {entry.details && <div className="text-xs text-muted-foreground mt-0.5 truncate">{entry.details}</div>}
                </div>
                <div className="text-xs text-muted-foreground whitespace-nowrap shrink-0">{formatDate(entry.timestamp)}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

src/components/admin/UserDetailModal.tsx.content:
import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { GetUsersOutputType, updateUser, deleteUser } from 'zite-endpoints-sdk';
import { Crown, Shield, ShieldCheck, User, UserX, Trash2, Check, Ban, UserCheck, Calendar, Clock, Mail, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

type UserRow = GetUsersOutputType['users'][0];
type RoleName = 'Owner' | 'Admin' | 'Moderator' | 'User' | 'Banned';

function roleRank(r?: string) {
  return r === 'Owner' ? 4 : r === 'Admin' ? 3 : r === 'Moderator' ? 2 : r === 'Banned' ? 0 : 1;
}

const ROLE_META: Record<string, { color: string; icon: React.ReactNode }> = {
  Owner:     { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', icon: <Crown className="w-3 h-3" /> },
  Admin:     { color: 'bg-primary/20 text-primary border-primary/30', icon: <Shield className="w-3 h-3" /> },
  Moderator: { color: 'bg-purple-500/20 text-purple-400 border-purple-500/30', icon: <ShieldCheck className="w-3 h-3" /> },
  User:      { color: 'bg-muted text-muted-foreground border-border', icon: <User className="w-3 h-3" /> },
  Banned:    { color: 'bg-destructive/20 text-destructive border-destructive/30', icon: <UserX className="w-3 h-3" /> },
};

const ASSIGNABLE_ROLES: Record<string, RoleName[]> = {
  Owner: ['Owner', 'Admin', 'Moderator', 'User', 'Banned'],
  Admin: ['Moderator', 'User', 'Banned'],
  Moderator: ['User', 'Banned'],
};

function fmt(iso?: string) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString();
}

interface Props {
  user: UserRow;
  myRole?: string;
  onClose: () => void;
  onUpdate: (updated: UserRow) => void;
  onDelete: (userId: string) => void;
}

export default function UserDetailModal({ user: initialUser, myRole, onClose, onUpdate, onDelete }: Props) {
  const [user, setUser] = useState(initialUser);
  const [firstName, setFirstName] = useState(user.firstName ?? '');
  const [lastName, setLastName] = useState(user.lastName ?? '');
  const [savingName, setSavingName] = useState(false);
  const [savingRole, setSavingRole] = useState(false);
  const [savingStatus, setSavingStatus] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  const myRank = roleRank(myRole);
  const targetRank = roleRank(user.role);
  const canModify = targetRank < myRank;
  const canEditName = myRank >= 3 && canModify;
  const canDelete = myRank >= 3 && canModify;
  const assignableRoles = ASSIGNABLE_ROLES[myRole ?? ''] ?? [];
  const meta = ROLE_META[user.role ?? 'User'] ?? ROLE_META.User;
  const initials = user.firstName
    ? (user.firstName[0] + (user.lastName?.[0] ?? '')).toUpperCase()
    : (user.email?.[0] ?? '?').toUpperCase();

  const applyUpdate = (patch: Partial<UserRow>) => {
    const updated = { ...user, ...patch };
    setUser(updated);
    onUpdate(updated);
  };

  const handleSaveName = async () => {
    setSavingName(true);
    try {
      await updateUser({ userId: user.id, firstName, lastName });
      applyUpdate({ firstName, lastName });
      toast.success('Name updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSavingName(false);
  };

  const handleRoleChange = async (role: RoleName) => {
    setSavingRole(true);
    try {
      await updateUser({ userId: user.id, role });
      applyUpdate({ role });
      toast.success('Role updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSavingRole(false);
  };

  const handleToggleActive = async () => {
    setSavingStatus(true);
    try {
      await updateUser({ userId: user.id, isActive: !user.isActive });
      applyUpdate({ isActive: !user.isActive });
      toast.success('Status updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSavingStatus(false);
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await deleteUser({ userId: user.id });
      onDelete(user.id);
      onClose();
      toast.success('User deleted');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); setDeleting(false); }
  };

  return (
    <>
      <Dialog open onOpenChange={onClose}>
        <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>User Details</DialogTitle>
          </DialogHeader>

          {/* Profile header */}
          <div className="flex items-center gap-4 pb-2 border-b border-border">
            <div className="w-14 h-14 rounded-full bg-primary/20 flex items-center justify-center text-xl font-bold text-primary shrink-0">
              {initials}
            </div>
            <div className="min-w-0">
              <div className="font-semibold text-foreground text-base truncate">
                {user.firstName || user.lastName ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() : '(No name set)'}
              </div>
              <div className="flex items-center gap-1 text-sm text-muted-foreground truncate">
                <Mail className="w-3 h-3 shrink-0" /> {user.email}
              </div>
              <div className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full border font-medium mt-1.5 ${meta.color}`}>
                {meta.icon} {user.role ?? 'User'}
              </div>
            </div>
          </div>

          <div className="space-y-5">
            {/* Name editing — Admin+ only */}
            {canEditName && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Edit Name</Label>
                <div className="flex gap-2">
                  <Input placeholder="First name" value={firstName} onChange={e => setFirstName(e.target.value)} className="text-sm" />
                  <Input placeholder="Last name" value={lastName} onChange={e => setLastName(e.target.value)} className="text-sm" />
                  <Button size="icon" className="shrink-0 h-9 w-9" onClick={handleSaveName} disabled={savingName}>
                    {savingName ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                  </Button>
                </div>
              </div>
            )}

            {/* Role change */}
            {canModify && assignableRoles.length > 0 && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Change Role</Label>
                <div className="flex items-center gap-2">
                  <Select value={user.role ?? 'User'} onValueChange={v => handleRoleChange(v as RoleName)} disabled={savingRole}>
                    <SelectTrigger className="text-sm flex-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {assignableRoles.map(r => (
                        <SelectItem key={r} value={r}>
                          <div className="flex items-center gap-2">{ROLE_META[r]?.icon} {r}</div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {savingRole && <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />}
                </div>
              </div>
            )}

            {/* Active status */}
            {canModify && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Account Status</Label>
                <div className="flex items-center justify-between bg-muted/30 border border-border rounded-lg px-4 py-3">
                  <div>
                    <div className="text-sm font-medium text-foreground">
                      {user.isActive !== false ? '✅ Active' : '🚫 Deactivated'}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {user.isActive !== false ? 'User can log in normally' : 'User cannot access the platform'}
                    </div>
                  </div>
                  <Button variant="outline" size="sm" onClick={handleToggleActive} disabled={savingStatus}>
                    {savingStatus
                      ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      : user.isActive !== false
                        ? <><Ban className="w-3.5 h-3.5 mr-1.5" />Deactivate</>
                        : <><UserCheck className="w-3.5 h-3.5 mr-1.5" />Activate</>
                    }
                  </Button>
                </div>
              </div>
            )}

            {/* Account info */}
            <div className="space-y-2">
              <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Account Info</Label>
              <div className="bg-muted/30 border border-border rounded-lg divide-y divide-border text-sm">
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Calendar className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="text-muted-foreground">Joined</span>
                  <span className="font-medium text-foreground ml-auto text-xs">{fmt(user.joinedAt)}</span>
                </div>
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Clock className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="text-muted-foreground">Last Active</span>
                  <span className="font-medium text-foreground ml-auto text-xs">{fmt(user.lastActive)}</span>
                </div>
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Badge variant="outline" className="text-xs">{user.id.slice(0, 8)}…</Badge>
                  <span className="text-muted-foreground text-xs">User ID</span>
                </div>
              </div>
            </div>

            {/* Delete */}
            {canDelete && (
              <Button variant="destructive" className="w-full" onClick={() => setConfirmDelete(true)} disabled={deleting}>
                {deleting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Trash2 className="w-4 h-4 mr-2" />}
                Delete User Account
              </Button>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete User</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete <strong>{user.email}</strong>? This action cannot be undone and will remove all their data.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

