import { BrowserRouter, Routes, Route } from 'react-router-dom';
import Home from './pages/Home';
import SubjectPage from './pages/SubjectPage';
import Navbar from './components/Navbar';

export default function App() {
  return (
    <BrowserRouter>
      <div className="min-h-screen bg-background">
        <Navbar />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/subject/:id" element={<SubjectPage />} />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export interface Lesson {
  title: string;
  description: string;
  content: string[];
  activity?: {
    type: 'quiz' | 'list' | 'fact';
    question?: string;
    options?: string[];
    answer?: number;
    items?: string[];
    fact?: string;
  };
}

export interface Subject {
  id: string;
  name: string;
  emoji: string;
  tagline: string;
  color: string;
  bgColor: string;
  borderColor: string;
  lessons: Lesson[];
}

export const subjects: Subject[] = [
  {
    id: 'reading',
    name: 'Reading',
    emoji: '📚',
    tagline: 'Explore stories and build comprehension skills',
    color: 'text-blue-700',
    bgColor: 'bg-blue-50',
    borderColor: 'border-blue-200',
    lessons: [
      {
        title: 'Understanding Main Idea',
        description: 'Learn how to find the central point of any passage.',
        content: [
          'The main idea is the most important point the author wants you to understand.',
          'It is often stated in the first or last sentence of a paragraph.',
          'Supporting details are facts or examples that back up the main idea.',
          'Ask yourself: "What is this passage mostly about?" to find the main idea.',
        ],
        activity: {
          type: 'quiz',
          question: 'Where is the main idea most commonly found in a paragraph?',
          options: ['In the middle', 'At the beginning or end', 'In every sentence', 'Only in pictures'],
          answer: 1,
        },
      },
      {
        title: 'Making Inferences',
        description: 'Use clues to figure out what the author implies.',
        content: [
          'An inference is a conclusion you draw from evidence and reasoning.',
          'Authors don\'t always state everything directly — readers must "read between the lines."',
          'Combine what the text says with what you already know.',
          'Example: If a character is shivering and looking for a coat, you can infer it\'s cold.',
        ],
        activity: {
          type: 'quiz',
          question: 'What is an inference?',
          options: ['A direct quote from the text', 'A conclusion drawn from clues', 'The title of a book', 'A type of punctuation'],
          answer: 1,
        },
      },
      {
        title: 'Story Elements',
        description: 'Identify characters, setting, plot, and theme.',
        content: [
          'Characters: The people or animals in the story.',
          'Setting: When and where the story takes place.',
          'Plot: The sequence of events (beginning, middle, end).',
          'Conflict: The problem or challenge the characters face.',
          'Theme: The central message or lesson of the story.',
        ],
        activity: {
          type: 'list',
          items: ['Characters', 'Setting', 'Plot', 'Conflict', 'Resolution', 'Theme'],
        },
      },
      {
        title: 'Figurative Language',
        description: 'Similes, metaphors, personification and more.',
        content: [
          'Simile: Comparing two things using "like" or "as" — "She runs like the wind."',
          'Metaphor: Saying one thing IS another — "He is a shining star."',
          'Personification: Giving human traits to non-human things — "The sun smiled down."',
          'Hyperbole: Extreme exaggeration — "I\'ve told you a million times!"',
          'Onomatopoeia: Words that sound like what they describe — "buzz," "crash," "sizzle."',
        ],
        activity: {
          type: 'quiz',
          question: '"The wind whispered through the trees." What type of figurative language is this?',
          options: ['Simile', 'Hyperbole', 'Personification', 'Onomatopoeia'],
          answer: 2,
        },
      },
    ],
  },
  {
    id: 'math',
    name: 'Mathematics',
    emoji: '🔢',
    tagline: 'Build number sense and problem-solving skills',
    color: 'text-green-700',
    bgColor: 'bg-green-50',
    borderColor: 'border-green-200',
    lessons: [
      {
        title: 'Fractions & Decimals',
        description: 'Understand parts of a whole and decimal notation.',
        content: [
          'A fraction represents a part of a whole: 1/2 means 1 out of 2 equal parts.',
          'The top number is the numerator; the bottom is the denominator.',
          'To convert a fraction to a decimal, divide the numerator by the denominator.',
          '1/4 = 0.25 | 1/2 = 0.50 | 3/4 = 0.75',
          'Equivalent fractions have the same value: 1/2 = 2/4 = 4/8.',
        ],
        activity: {
          type: 'quiz',
          question: 'What is 3/4 as a decimal?',
          options: ['0.34', '0.43', '0.75', '0.25'],
          answer: 2,
        },
      },
      {
        title: 'Order of Operations',
        description: 'Learn PEMDAS to solve expressions correctly.',
        content: [
          'PEMDAS stands for: Parentheses, Exponents, Multiplication, Division, Addition, Subtraction.',
          'Always solve what\'s inside parentheses first.',
          'Then handle exponents (powers and roots).',
          'Then multiply and divide from left to right.',
          'Finally, add and subtract from left to right.',
          'Example: 2 + 3 × 4 = 2 + 12 = 14 (not 20!)',
        ],
        activity: {
          type: 'quiz',
          question: 'What is 10 + 2 × 5?',
          options: ['60', '20', '25', '100'],
          answer: 1,
        },
      },
      {
        title: 'Geometry Basics',
        description: 'Shapes, angles, perimeter, and area.',
        content: [
          'Perimeter: The total distance around a shape. P = sum of all sides.',
          'Area of a rectangle: A = length × width.',
          'Area of a triangle: A = ½ × base × height.',
          'A right angle measures 90°. An acute angle is less than 90°. An obtuse angle is more than 90°.',
          'Pi (π ≈ 3.14) is used to find the circumference and area of circles.',
        ],
        activity: {
          type: 'quiz',
          question: 'What is the area of a rectangle with length 6 and width 4?',
          options: ['10', '20', '24', '48'],
          answer: 2,
        },
      },
      {
        title: 'Algebra Fundamentals',
        description: 'Solve for unknowns using equations.',
        content: [
          'A variable is a letter that represents an unknown number (e.g., x, y, n).',
          'An equation states that two expressions are equal: 3x + 2 = 11.',
          'To solve for x, use inverse operations (undo what was done).',
          '3x + 2 = 11 → subtract 2 → 3x = 9 → divide by 3 → x = 3.',
          'Always do the same operation to both sides of the equation.',
        ],
        activity: {
          type: 'quiz',
          question: 'Solve: 2x + 4 = 12. What is x?',
          options: ['3', '4', '6', '8'],
          answer: 1,
        },
      },
    ],
  },
  {
    id: 'science',
    name: 'Science',
    emoji: '🔬',
    tagline: 'Discover the wonders of the natural world',
    color: 'text-purple-700',
    bgColor: 'bg-purple-50',
    borderColor: 'border-purple-200',
    lessons: [
      {
        title: 'The Scientific Method',
        description: 'Learn the steps scientists use to investigate.',
        content: [
          '1. Observation: Notice something interesting in the world around you.',
          '2. Question: Ask a specific, testable question about your observation.',
          '3. Hypothesis: Make an educated guess (prediction) about the answer.',
          '4. Experiment: Design and conduct a controlled test.',
          '5. Data: Record your measurements and observations carefully.',
          '6. Conclusion: Analyze results and determine if your hypothesis was correct.',
        ],
        activity: {
          type: 'list',
          items: ['Observation', 'Question', 'Hypothesis', 'Experiment', 'Data Collection', 'Conclusion'],
        },
      },
      {
        title: 'Cells: The Building Blocks of Life',
        description: 'Explore plant and animal cells.',
        content: [
          'All living things are made of cells — the smallest unit of life.',
          'Animal cells have a cell membrane, nucleus, cytoplasm, and mitochondria.',
          'Plant cells also have a cell wall, chloroplasts, and a large central vacuole.',
          'The nucleus is the "control center" containing DNA.',
          'Mitochondria produce energy through cellular respiration.',
          'Chloroplasts in plant cells capture sunlight for photosynthesis.',
        ],
        activity: {
          type: 'quiz',
          question: 'Which organelle is known as the "powerhouse of the cell"?',
          options: ['Nucleus', 'Chloroplast', 'Mitochondria', 'Cell Wall'],
          answer: 2,
        },
      },
      {
        title: 'The Solar System',
        description: 'Explore our sun, planets, and beyond.',
        content: [
          'Our solar system has 8 planets orbiting the Sun.',
          'Inner planets (rocky): Mercury, Venus, Earth, Mars.',
          'Outer planets (gas giants): Jupiter, Saturn, Uranus, Neptune.',
          'Earth is the only known planet with liquid water on the surface.',
          'Jupiter is the largest planet; Mercury is the smallest.',
          'A light-year is the distance light travels in one year (~5.88 trillion miles).',
        ],
        activity: {
          type: 'quiz',
          question: 'How many planets are in our solar system?',
          options: ['7', '8', '9', '10'],
          answer: 1,
        },
      },
      {
        title: 'States of Matter',
        description: 'Solid, liquid, gas, and plasma.',
        content: [
