import { useParams, Link } from 'react-router-dom';
import { subjects } from '../data/subjects';
import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronDown, ChevronUp, CheckCircle2, XCircle, Lightbulb, List, HelpCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';

export default function SubjectPage() {
  const { id } = useParams();
  const subject = subjects.find((s) => s.id === id);
  const [openLesson, setOpenLesson] = useState<number | null>(0);

  if (!subject) {
    return (
      <div className="container mx-auto px-4 py-20 text-center">
        <div className="text-6xl mb-4">🔍</div>
        <h2 className="text-2xl font-bold mb-2">Subject not found</h2>
        <Link to="/" className="text-primary hover:underline">Go back home</Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen">
      {/* Header */}
      <div className={`${subject.bgColor} border-b ${subject.borderColor} py-12 px-4`}>
        <div className="container mx-auto max-w-3xl">
          <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }}>
            <div className="text-6xl mb-3">{subject.emoji}</div>
            <h1 className={`text-4xl font-extrabold ${subject.color} mb-2`}>{subject.name}</h1>
            <p className="text-muted-foreground text-lg mb-4">{subject.tagline}</p>
            <Badge variant="secondary">{subject.lessons.length} Lessons</Badge>
          </motion.div>
        </div>
      </div>

      {/* Lessons */}
      <div className="container mx-auto px-4 py-10 max-w-3xl">
        <h2 className="text-xl font-bold text-foreground mb-6">📖 Lessons</h2>
        <div className="space-y-4">
          {subject.lessons.map((lesson, idx) => (
            <motion.div
              key={idx}
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: idx * 0.07 }}
              className={`border-2 ${subject.borderColor} rounded-2xl overflow-hidden bg-card shadow-sm`}
            >
              <button
                className="w-full px-6 py-4 flex items-center justify-between text-left hover:bg-muted/30 transition-colors"
                onClick={() => setOpenLesson(openLesson === idx ? null : idx)}
              >
                <div className="flex items-center gap-3">
                  <span className={`font-bold text-lg w-7 h-7 rounded-full flex items-center justify-center text-sm ${subject.bgColor} ${subject.color} border ${subject.borderColor}`}>
                    {idx + 1}
                  </span>
                  <div>
                    <div className="font-semibold text-foreground">{lesson.title}</div>
                    <div className="text-sm text-muted-foreground">{lesson.description}</div>
                  </div>
                </div>
                {openLesson === idx ? (
                  <ChevronUp className={`w-5 h-5 ${subject.color} shrink-0`} />
                ) : (
                  <ChevronDown className="w-5 h-5 text-muted-foreground shrink-0" />
                )}
              </button>

              <AnimatePresence initial={false}>
                {openLesson === idx && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.25 }}
                  >
                    <div className={`px-6 pb-6 pt-2 border-t ${subject.borderColor} bg-background`}>
                      {/* Content */}
                      <ul className="space-y-2 mb-6">
                        {lesson.content.map((point, i) => (
                          <li key={i} className="flex items-start gap-2 text-sm text-foreground/90">
                            <span className={`mt-1 shrink-0 w-2 h-2 rounded-full ${subject.bgColor} border ${subject.borderColor}`} />
                            <span>{point}</span>
                          </li>
                        ))}
                      </ul>

                      {/* Activity */}
                      {lesson.activity && (
                        <ActivityBlock activity={lesson.activity} subjectColor={subject.color} subjectBg={subject.bgColor} subjectBorder={subject.borderColor} />
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
        </div>

        <div className="mt-10 text-center">
          <Link to="/">
            <Button variant="outline">← Back to All Subjects</Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

interface ActivityProps {
  activity: NonNullable<import('../data/subjects').Lesson['activity']>;
  subjectColor: string;
  subjectBg: string;
  subjectBorder: string;
}

function ActivityBlock({ activity, subjectColor, subjectBg, subjectBorder }: ActivityProps) {
  const [selected, setSelected] = useState<number | null>(null);
  const [revealed, setRevealed] = useState(false);

  if (activity.type === 'fact') {
    return (
      <div className={`rounded-xl ${subjectBg} border ${subjectBorder} p-4 flex items-start gap-3`}>
        <Lightbulb className={`w-5 h-5 mt-0.5 shrink-0 ${subjectColor}`} />
        <div>
          <div className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-1">Fun Fact</div>
          <p className="text-sm text-foreground">{activity.fact}</p>
        </div>
      </div>
    );
  }

  if (activity.type === 'list') {
    return (
      <div className={`rounded-xl ${subjectBg} border ${subjectBorder} p-4`}>
        <div className="flex items-center gap-2 mb-3">
          <List className={`w-4 h-4 ${subjectColor}`} />
          <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Key Terms</span>
        </div>
        <div className="flex flex-wrap gap-2">
          {activity.items?.map((item, i) => (
            <span key={i} className={`text-sm px-3 py-1 rounded-full border ${subjectBorder} bg-background font-medium ${subjectColor}`}>
              {item}
            </span>
          ))}
        </div>
      </div>
    );
  }

  if (activity.type === 'quiz') {
    const isCorrect = selected === activity.answer;
    return (
      <div className={`rounded-xl ${subjectBg} border ${subjectBorder} p-4`}>
        <div className="flex items-center gap-2 mb-3">
          <HelpCircle className={`w-4 h-4 ${subjectColor}`} />
          <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Quick Quiz</span>
        </div>
        <p className="text-sm font-medium text-foreground mb-3">{activity.question}</p>
        <div className="space-y-2">
          {activity.options?.map((opt, i) => {
            const isSelected = selected === i;
            const showResult = selected !== null;
            const isAnswerKey = i === activity.answer;
            let btnClass = 'border-border bg-background text-foreground hover:bg-muted/50';
            if (showResult && isSelected && isCorrect) btnClass = 'border-green-400 bg-green-50 text-green-800';
            if (showResult && isSelected && !isCorrect) btnClass = 'border-red-400 bg-red-50 text-red-800';
            if (showResult && !isSelected && isAnswerKey) btnClass = 'border-green-400 bg-green-50 text-green-800';
            return (
              <button
                key={i}
                disabled={selected !== null}
                onClick={() => setSelected(i)}
                className={`w-full text-left text-sm px-4 py-2 rounded-lg border-2 transition-colors flex items-center justify-between ${btnClass}`}
              >
                <span>{opt}</span>
                {showResult && isAnswerKey && <CheckCircle2 className="w-4 h-4 text-green-600" />}
                {showResult && isSelected && !isCorrect && i === selected && <XCircle className="w-4 h-4 text-red-500" />}
              </button>
            );
          })}
        </div>
        {selected !== null && (
          <motion.p
            initial={{ opacity: 0, y: 4 }}
            animate={{ opacity: 1, y: 0 }}
            className={`mt-3 text-sm font-medium ${isCorrect ? 'text-green-700' : 'text-red-700'}`}
          >
            {isCorrect ? '🎉 Correct! Great job!' : `❌ Not quite. The correct answer is: "${activity.options?.[activity.answer ?? 0]}"`}
          </motion.p>
        )}
        {selected !== null && (
          <Button
            size="sm"
            variant="ghost"
            className="mt-2 text-xs"
            onClick={() => { setSelected(null); setRevealed(false); }}
          >
            Try Again
          </Button>
        )}
        {revealed && <span className="hidden">{revealed}</span>}
      </div>
    );
  }

  return null;
}

