import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Check if the current user is an admin',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    isAdmin: z.boolean(),
    user: z.object({
      id: z.string(),
      email: z.string(),
      firstName: z.string().optional(),
      lastName: z.string().optional(),
      role: z.string().optional(),
    }),
  }),
  execute: async ({ context }) => {
    const record = await Users.findOne({ id: context.user.id });
    const isAdmin = record?.role === 'Admin';
    return {
      isAdmin,
      user: {
        id: context.user.id,
        email: context.user.email,
        firstName: context.user.firstName,
        lastName: context.user.lastName,
        role: record?.role,
      },
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get all users - admin only',
  authenticated: true,
  inputSchema: z.object({
    search: z.string().optional(),
    roleFilter: z.string().optional(),
  }),
  outputSchema: z.object({
    users: z.array(z.object({
      id: z.string(),
      email: z.string().optional(),
      firstName: z.string().optional(),
      lastName: z.string().optional(),
      role: z.string().optional(),
      joinedAt: z.string().optional(),
      lastActive: z.string().optional(),
      isActive: z.boolean().optional(),
    })),
    total: z.number(),
  }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    const { records } = await Users.findAll({ limit: 500 });
    let filtered = records;
    if (input.search) {
      const q = input.search.toLowerCase();
      filtered = filtered.filter(u =>
        u.email?.toLowerCase().includes(q) ||
        u.firstName?.toLowerCase().includes(q) ||
        u.lastName?.toLowerCase().includes(q)
      );
    }
    if (input.roleFilter && input.roleFilter !== 'all') {
      filtered = filtered.filter(u => u.role?.toLowerCase() === input.roleFilter?.toLowerCase());
    }
    return {
      users: filtered.map(u => ({
        id: u.id,
        email: u.email,
        firstName: u.firstName,
        lastName: u.lastName,
        role: u.role,
        joinedAt: u.joinedAt,
        lastActive: u.lastActive,
        isActive: u.isActive,
      })),
      total: filtered.length,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Update a user role or status - admin only',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    role: z.enum(['Admin', 'User', 'Banned']).optional(),
    isActive: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    if (input.userId === context.user.id) {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'You cannot modify your own account' });
    }
    const updates: Partial<{ role: string; isActive: boolean }> = {};
    if (input.role !== undefined) updates.role = input.role;
    if (input.isActive !== undefined) updates.isActive = input.isActive;
    await Users.update({ id: input.userId, record: updates });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Delete a user - admin only',
  authenticated: true,
  inputSchema: z.object({ userId: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    if (input.userId === context.user.id) {
      throw new ZiteError({ code: 'BAD_REQUEST', message: 'You cannot delete your own account' });
    }
    await Users.delete({ id: input.userId });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, Announcements, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get all announcements - admin only',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    announcements: z.array(z.object({
      id: z.string(),
      title: z.string().optional(),
      message: z.string().optional(),
      status: z.string().optional(),
      postedAt: z.string().optional(),
      postedBy: z.string().optional(),
    })),
  }),
  execute: async ({ context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    const { records } = await Announcements.findAll({ limit: 100 });
    return {
      announcements: records.map(a => ({
        id: a.id,
        title: a.title,
        message: a.message,
        status: a.status,
        postedAt: a.postedAt,
        postedBy: a.postedBy,
      })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Announcements, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create, update, or delete an announcement - admin only',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['create', 'update', 'delete']),
    id: z.string().optional(),
    title: z.string().optional(),
    message: z.string().optional(),
    status: z.enum(['Active', 'Draft', 'Archived']).optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string().optional() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    if (input.action === 'create') {
      const record = await Announcements.create({
        record: {
          title: input.title,
          message: input.message,
          status: input.status ?? 'Draft',
          postedAt: new Date().toISOString(),
          postedBy: context.user.email,
        },
      });
      return { success: true, id: record.id };
    }
    if (input.action === 'update' && input.id) {
      await Announcements.update({
        id: input.id,
        record: { title: input.title, message: input.message, status: input.status },
      });
      return { success: true, id: input.id };
    }
    if (input.action === 'delete' && input.id) {
      await Announcements.delete({ id: input.id });
      return { success: true };
    }
    throw new ZiteError({ code: 'BAD_REQUEST', message: 'Invalid action' });
  },
});

