import { z } from 'zod';
import { createEndpoint, SiteSettings, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Update a site setting - admin only',
  authenticated: true,
  inputSchema: z.object({
    key: z.string(),
    value: z.string(),
    description: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    const existing = await SiteSettings.findOne({ filters: { settingKey: input.key } });
    if (existing) {
      await SiteSettings.update({ id: existing.id, record: { settingValue: input.value } });
    } else {
      await SiteSettings.create({
        record: { settingKey: input.key, settingValue: input.value, description: input.description ?? '' },
      });
    }
    return { success: true };
  },
});

import { useState, useEffect } from 'react';
import { getUsers, GetUsersOutputType, updateUser, deleteUser } from 'zite-endpoints-sdk';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Search, Trash2, ShieldCheck, UserX, User, RefreshCw } from 'lucide-react';
import { toast } from 'sonner';

type UserRow = GetUsersOutputType['users'][0];

const ROLE_COLORS: Record<string, string> = {
  Admin: 'bg-primary/20 text-primary border-primary/30',
  User: 'bg-muted text-muted-foreground border-border',
  Banned: 'bg-destructive/20 text-destructive border-destructive/30',
};

export default function UserManager() {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [deleteTarget, setDeleteTarget] = useState<UserRow | null>(null);
  const [updating, setUpdating] = useState<string | null>(null);

  const load = async (s = search, r = roleFilter) => {
    setLoading(true);
    try {
      const res = await getUsers({ search: s, roleFilter: r });
      setUsers(res.users);
    } catch { toast.error('Failed to load users'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleRoleChange = async (userId: string, role: 'Admin' | 'User' | 'Banned') => {
    setUpdating(userId);
    try {
      await updateUser({ userId, role });
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, role } : u));
      toast.success('Role updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed to update'); }
    setUpdating(null);
  };

  const handleToggleActive = async (user: UserRow) => {
    setUpdating(user.id);
    try {
      await updateUser({ userId: user.id, isActive: !user.isActive });
      setUsers(prev => prev.map(u => u.id === user.id ? { ...u, isActive: !u.isActive } : u));
      toast.success('Status updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed to update'); }
    setUpdating(null);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      await deleteUser({ userId: deleteTarget.id });
      setUsers(prev => prev.filter(u => u.id !== deleteTarget.id));
      toast.success('User deleted');
    } catch (e: any) { toast.error(e?.message ?? 'Failed to delete'); }
    setDeleteTarget(null);
  };

  const handleSearch = (s: string) => { setSearch(s); load(s, roleFilter); };
  const handleFilter = (r: string) => { setRoleFilter(r); load(search, r); };

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search users..." className="pl-9" value={search} onChange={e => handleSearch(e.target.value)} />
        </div>
        <Select value={roleFilter} onValueChange={handleFilter}>
          <SelectTrigger className="w-36">
            <SelectValue placeholder="All roles" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Roles</SelectItem>
            <SelectItem value="Admin">Admin</SelectItem>
            <SelectItem value="User">User</SelectItem>
            <SelectItem value="Banned">Banned</SelectItem>
          </SelectContent>
        </Select>
        <Button variant="outline" size="icon" onClick={() => load()} title="Refresh">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      <div className="text-xs text-muted-foreground">{users.length} user{users.length !== 1 ? 's' : ''} found</div>

      {loading ? (
        <div className="space-y-2">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="h-14 rounded-lg bg-muted/40 animate-pulse" />
          ))}
        </div>
      ) : users.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No users found</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {users.map(user => (
            <div key={user.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3">
              <div className="w-8 h-8 rounded-full bg-primary/20 flex items-center justify-center shrink-0">
                <User className="w-4 h-4 text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground truncate">
                  {user.firstName || user.lastName ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() : user.email}
                </div>
                <div className="text-xs text-muted-foreground truncate">{user.email}</div>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span className={`text-xs px-2 py-0.5 rounded-full border font-medium ${ROLE_COLORS[user.role ?? 'User'] ?? ROLE_COLORS.User}`}>
                  {user.role ?? 'User'}
                </span>
                <Select
                  value={user.role ?? 'User'}
                  onValueChange={(v) => handleRoleChange(user.id, v as 'Admin' | 'User' | 'Banned')}
                  disabled={updating === user.id}
                >
                  <SelectTrigger className="h-7 w-24 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Admin">Admin</SelectItem>
                    <SelectItem value="User">User</SelectItem>
                    <SelectItem value="Banned">Banned</SelectItem>
                  </SelectContent>
                </Select>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  title={user.isActive ? 'Deactivate' : 'Activate'}
                  onClick={() => handleToggleActive(user)}
                  disabled={updating === user.id}
                >
                  {user.isActive !== false ? (
                    <ShieldCheck className="w-3.5 h-3.5 text-primary" />
                  ) : (
                    <UserX className="w-3.5 h-3.5 text-muted-foreground" />
                  )}
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7 hover:text-destructive"
                  onClick={() => setDeleteTarget(user)}
                  disabled={updating === user.id}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete User</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to permanently delete <strong>{deleteTarget?.email}</strong>? This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { getAnnouncements, manageAnnouncement, GetAnnouncementsOutputType } from 'zite-endpoints-sdk';
