type AdminTab = 'overview' | 'users' | 'announcements' | 'settings';

export default function SecretHub({ onClose }: { onClose: () => void }) {
  const [tab, setTab] = useState<'games' | 'proxies' | 'admin'>('games');
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [isAdmin, setIsAdmin] = useState(false);
  const [adminChecked, setAdminChecked] = useState(false);
  const [adminTab, setAdminTab] = useState<AdminTab>('overview');

  useEffect(() => {
    if (!isLoading && user) {
      checkAdmin({}).then(res => {
        setIsAdmin(res.isAdmin);
        setAdminChecked(true);
      }).catch(() => setAdminChecked(true));
    } else if (!isLoading) {
      setAdminChecked(true);
    }
  }, [user, isLoading]);

  return (
    <>
      <Toaster />
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[9999] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4"
      >
        <motion.div
          initial={{ scale: 0.9, y: 20 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.9, y: 20 }}
          className="bg-card border border-border rounded-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl"
        >
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/30">
            <div className="flex items-center gap-2">
              <Zap className="w-5 h-5 text-primary" />
              <span className="font-bold text-foreground text-lg">Genizy Hub</span>
              <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium">SECRET</span>
              {isAdmin && (
                <span className="text-xs bg-red-500/20 text-red-400 border border-red-500/30 px-2 py-0.5 rounded-full font-medium">ADMIN</span>
              )}
            </div>
            <div className="flex items-center gap-2">
              {user && <span className="text-xs text-muted-foreground hidden sm:block">{user.email}</span>}
              <button onClick={onClose} className="text-muted-foreground hover:text-foreground transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Tabs */}
          <div className="flex border-b border-border overflow-x-auto">
            {[
              { id: 'games', label: 'Games', icon: Gamepad2 },
              { id: 'proxies', label: 'Proxies', icon: Globe },
              { id: 'admin', label: 'Admin', icon: Shield },
            ].map(t => (
              <button
                key={t.id}
                onClick={() => setTab(t.id as typeof tab)}
                className={`flex items-center gap-2 px-6 py-3 text-sm font-medium transition-colors border-b-2 whitespace-nowrap ${
                  tab === t.id ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
