function AdminSection({ user, isAdmin, adminChecked, isLoading, loginWithRedirect, adminTab, setAdminTab }: {
  user: any; isAdmin: boolean; adminChecked: boolean; isLoading: boolean;
  loginWithRedirect: (opts?: any) => void; adminTab: AdminTab; setAdminTab: (t: AdminTab) => void;
}) {
  if (isLoading || !adminChecked) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
        <p className="text-sm text-muted-foreground">Checking access...</p>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Admin Access</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">You need to be signed in with an admin account to access this panel.</p>
        <Button onClick={() => loginWithRedirect({ redirectUrl: window.location.href })} className="flex items-center gap-2">
          <LogIn className="w-4 h-4" /> Sign In
        </Button>
      </div>
    );
  }

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Access Denied</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">
          Your account (<strong>{user.email}</strong>) does not have admin privileges.
        </p>
      </div>
    );
  }

  const adminTabs = [
    { id: 'overview', label: 'Overview', icon: BarChart3 },
    { id: 'users', label: 'Users', icon: Users },
    { id: 'announcements', label: 'Announcements', icon: Megaphone },
    { id: 'settings', label: 'Site Controls', icon: Settings },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 text-green-400 text-sm font-medium mb-2">
        <Shield className="w-4 h-4" />
        Logged in as admin: {user.email}
      </div>

      {/* Sub-tabs */}
      <div className="flex gap-1 bg-muted/40 p-1 rounded-xl flex-wrap">
        {adminTabs.map(t => (
          <button
            key={t.id}
            onClick={() => setAdminTab(t.id as AdminTab)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
              adminTab === t.id ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            <t.icon className="w-3.5 h-3.5" />
            {t.label}
          </button>
        ))}
      </div>

      <AnimatePresence mode="wait">
        <motion.div key={adminTab} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.15 }}>
          {adminTab === 'overview' && <AdminOverview />}
          {adminTab === 'users' && <UserManager />}
          {adminTab === 'announcements' && <AnnouncementManager />}
          {adminTab === 'settings' && <SiteControls />}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

function AdminOverview() {
  const stats = [
    { label: 'Total Subjects', value: '8', icon: '📚', change: 'All active' },
    { label: 'Total Lessons', value: '32', icon: '📖', change: 'All published' },
