              <div>
                <p className="text-muted-foreground text-sm mb-4">Click any game to open it in a new tab.</p>
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                  {games.map(game => (
                    <a key={game.name} href={game.url} target="_blank" rel="noopener noreferrer"
                      className="group bg-muted/40 hover:bg-primary/10 border border-border hover:border-primary/50 rounded-xl p-4 transition-all duration-200 hover:-translate-y-0.5">
                      <div className="text-3xl mb-2">{game.emoji}</div>
                      <div className="font-semibold text-sm text-foreground group-hover:text-primary transition-colors flex items-center gap-1">
                        {game.name} <ExternalLink className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </div>
                      <div className="text-xs text-muted-foreground mt-0.5 leading-snug">{game.desc}</div>
                    </a>
                  ))}
                </div>
              </div>
            )}

            {tab === 'proxies' && (
              <div>
                <p className="text-muted-foreground text-sm mb-4">Access web proxies to browse freely. Links open in a new tab.</p>
                <div className="space-y-3">
                  {proxies.map(proxy => (
                    <a key={proxy.name} href={proxy.url} target="_blank" rel="noopener noreferrer"
                      className="group flex items-center justify-between bg-muted/40 hover:bg-primary/10 border border-border hover:border-primary/50 rounded-xl px-5 py-4 transition-all duration-200">
                      <div className="flex items-center gap-4">
                        <span className="text-2xl">{proxy.emoji}</span>
                        <div>
                          <div className="font-semibold text-foreground group-hover:text-primary transition-colors">{proxy.name}</div>
                          <div className="text-xs text-muted-foreground">{proxy.desc}</div>
                        </div>
                      </div>
                      <div className="flex items-center gap-1 text-xs text-muted-foreground group-hover:text-primary transition-colors">
                        Open <ChevronRight className="w-4 h-4" />
                      </div>
                    </a>
                  ))}
                </div>
              </div>
            )}

            {tab === 'admin' && (
              <AdminSection
                user={user}
                isAdmin={isAdmin}
                adminChecked={adminChecked}
                isLoading={isLoading}
                loginWithRedirect={loginWithRedirect}
                adminTab={adminTab}
                setAdminTab={setAdminTab}
              />
            )}
          </div>
        </motion.div>
      </motion.div>
    </>
  );
}

function AdminSection({ user, isAdmin, adminChecked, isLoading, loginWithRedirect, adminTab, setAdminTab }: {
  user: any; isAdmin: boolean; adminChecked: boolean; isLoading: boolean;
  loginWithRedirect: (opts?: any) => void; adminTab: AdminTab; setAdminTab: (t: AdminTab) => void;
}) {
  if (isLoading || !adminChecked) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
        <p className="text-sm text-muted-foreground">Checking access...</p>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Admin Access</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">You need to be signed in with an admin account to access this panel.</p>
        <Button onClick={() => loginWithRedirect({ redirectUrl: window.location.href })} className="flex items-center gap-2">
          <LogIn className="w-4 h-4" /> Sign In
        </Button>
      </div>
    );
  }

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Access Denied</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">
          Your account (<strong>{user.email}</strong>) does not have admin privileges.
        </p>
      </div>
    );
  }

  const adminTabs = [
    { id: 'overview', label: 'Overview', icon: BarChart3 },
    { id: 'users', label: 'Users', icon: Users },
    { id: 'announcements', label: 'Announcements', icon: Megaphone },
    { id: 'settings', label: 'Site Controls', icon: Settings },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 text-green-400 text-sm font-medium mb-2">
        <Shield className="w-4 h-4" />
        Logged in as admin: {user.email}
      </div>

      {/* Sub-tabs */}
      <div className="flex gap-1 bg-muted/40 p-1 rounded-xl flex-wrap">
        {adminTabs.map(t => (
          <button
            key={t.id}
            onClick={() => setAdminTab(t.id as AdminTab)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
              adminTab === t.id ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            <t.icon className="w-3.5 h-3.5" />
            {t.label}
          </button>
        ))}
      </div>

      <AnimatePresence mode="wait">
        <motion.div key={adminTab} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.15 }}>
          {adminTab === 'overview' && <AdminOverview />}
          {adminTab === 'users' && <UserManager />}
          {adminTab === 'announcements' && <AnnouncementManager />}
          {adminTab === 'settings' && <SiteControls />}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

function AdminOverview() {
  const stats = [
    { label: 'Total Subjects', value: '8', icon: '📚', change: 'All active' },
    { label: 'Total Lessons', value: '32', icon: '📖', change: 'All published' },
    { label: 'Games Available', value: '12', icon: '🎮', change: 'In games hub' },
    { label: 'Proxies Listed', value: '6', icon: '🌐', change: 'In proxy hub' },
  ];
  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        {stats.map(s => (
          <div key={s.label} className="bg-muted/40 border border-border rounded-xl p-4">
            <div className="text-2xl mb-1">{s.icon}</div>
            <div className="text-xs text-muted-foreground">{s.label}</div>
            <div className="text-2xl font-bold text-foreground">{s.value}</div>
            <div className="text-xs text-primary mt-0.5">{s.change}</div>
          </div>
        ))}
      </div>
      <div className="bg-muted/40 border border-border rounded-xl p-4 text-sm text-muted-foreground">
        <p className="font-medium text-foreground mb-1">👋 Welcome to the Admin Panel</p>
        <p>Use the tabs above to manage users, post announcements, and control site settings. All changes take effect immediately.</p>
      </div>
    </div>
  );
}

import { Link, useLocation } from 'react-router-dom';
