                <Button variant="ghost" size="sm" onClick={() => logout()} className="flex items-center gap-1.5 text-muted-foreground hover:text-foreground">
                  <LogOut className="w-4 h-4" />
                  <span className="hidden sm:inline">Sign Out</span>
