import { z } from 'zod';
import { createEndpoint, HubTabs, HubItems } from 'zite-integrations-backend-sdk';

const itemSchema = z.object({
  id: z.string(),
  itemName: z.string().optional(),
  url: z.string().optional(),
  emoji: z.string().optional(),
  description: z.string().optional(),
});

const tabSchema = z.object({
  id: z.string(),
  tabName: z.string().optional(),
  emoji: z.string().optional(),
  tabType: z.string().optional(),
  sortOrder: z.number().optional(),
  items: z.array(itemSchema),
});

export default createEndpoint({
  description: 'Get all hub tabs with their items (public)',
  inputSchema: z.object({}),
  outputSchema: z.object({ tabs: z.array(tabSchema) }),
  execute: async () => {
    const [{ records: tabs }, { records: items }] = await Promise.all([
      HubTabs.findAll({ limit: 100 }),
      HubItems.findAll({ limit: 500 }),
    ]);
    const sorted = [...tabs].sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));
    return {
      tabs: sorted.map(t => ({
        id: t.id,
        tabName: t.tabName,
        emoji: t.emoji,
        tabType: t.tabType,
        sortOrder: t.sortOrder,
        items: items
          .filter(i => i.tabId === t.id)
          .map(i => ({ id: i.id, itemName: i.itemName, url: i.url, emoji: i.emoji, description: i.description })),
      })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint, HubTabs, HubItems, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create, update, or delete a hub tab — admin only',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['create', 'update', 'delete']),
    id: z.string().optional(),
    tabName: z.string().optional(),
    emoji: z.string().optional(),
    tabType: z.enum(['Single', 'Multiple']).optional(),
    sortOrder: z.number().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string().optional() }),
  execute: async ({ input, context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    if (caller?.role !== 'Admin') throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin only' });

    if (input.action === 'create') {
      const rec = await HubTabs.create({
        record: { tabName: input.tabName, emoji: input.emoji, tabType: input.tabType ?? 'Multiple', sortOrder: input.sortOrder ?? 0 },
      });
      return { success: true, id: rec.id };
    }
    if (input.action === 'update' && input.id) {
      await HubTabs.update({ id: input.id, record: { tabName: input.tabName, emoji: input.emoji, tabType: input.tabType, sortOrder: input.sortOrder } });
      return { success: true, id: input.id };
    }
    if (input.action === 'delete' && input.id) {
      // Delete all items belonging to this tab first
      const { records: items } = await HubItems.findAll({ filters: { tabId: input.id } });
      await Promise.all(items.map(i => HubItems.delete({ id: i.id })));
      await HubTabs.delete({ id: input.id });
      return { success: true };
    }
    throw new ZiteError({ code: 'BAD_REQUEST', message: 'Invalid action' });
  },
});

import { z } from 'zod';
import { createEndpoint, HubItems, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create, update, or delete a hub item — admin only',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['create', 'update', 'delete']),
    id: z.string().optional(),
    tabId: z.string().optional(),
    itemName: z.string().optional(),
    url: z.string().optional(),
    emoji: z.string().optional(),
    description: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string().optional() }),
  execute: async ({ input, context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    if (caller?.role !== 'Admin') throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin only' });

    if (input.action === 'create') {
      const rec = await HubItems.create({
        record: { itemName: input.itemName, url: input.url, emoji: input.emoji, description: input.description, tabId: input.tabId },
      });
      return { success: true, id: rec.id };
    }
    if (input.action === 'update' && input.id) {
      await HubItems.update({ id: input.id, record: { itemName: input.itemName, url: input.url, emoji: input.emoji, description: input.description } });
      return { success: true, id: input.id };
    }
    if (input.action === 'delete' && input.id) {
      await HubItems.delete({ id: input.id });
      return { success: true };
    }
    throw new ZiteError({ code: 'BAD_REQUEST', message: 'Invalid action' });
  },
});

import { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Maximize2, Minimize2, ExternalLink, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';

interface Props {
  url: string;
  title: string;
  emoji?: string;
  onClose: () => void;
}

export function openCloaked(url: string, title: string) {
  const w = window.open('about:blank', '_blank');
  if (!w) return;
  w.document.write(`<!DOCTYPE html><html><head><title>${title}</title><style>*{margin:0;padding:0;box-sizing:border-box}html,body,iframe{width:100%;height:100%;border:none;overflow:hidden}</style></head><body><iframe src="${url}" allowfullscreen allow="autoplay; fullscreen"></iframe></body></html>`);
  w.document.close();
}

export default function IframeViewer({ url, title, emoji, onClose }: Props) {
  const [isFullscreen, setIsFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const toggleFullscreen = () => {
    if (!isFullscreen) {
      containerRef.current?.requestFullscreen?.().catch(() => {});
    } else {
      document.exitFullscreen?.().catch(() => {});
    }
    setIsFullscreen(!isFullscreen);
  };

  return (
    <AnimatePresence>
      <motion.div
        ref={containerRef}
        initial={{ opacity: 0, scale: 0.97 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.97 }}
        className="fixed inset-0 z-[10000] bg-black flex flex-col"
      >
        {/* Toolbar */}
        <div className="flex items-center gap-2 px-3 py-2 bg-card border-b border-border shrink-0">
          <button onClick={onClose} className="flex items-center gap-1.5 text-muted-foreground hover:text-foreground transition-colors text-sm">
            <ArrowLeft className="w-4 h-4" /> Back
          </button>
          <div className="flex-1 flex items-center justify-center gap-2">
            {emoji && <span>{emoji}</span>}
            <span className="text-sm font-medium text-foreground truncate max-w-xs">{title}</span>
          </div>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 text-muted-foreground hover:text-foreground"
              title="Open cloaked in new tab"
              onClick={() => openCloaked(url, title)}
            >
              <ExternalLink className="w-4 h-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 text-muted-foreground hover:text-foreground"
              title={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
              onClick={toggleFullscreen}
            >
              {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
            </Button>
            <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-foreground" onClick={onClose}>
              <X className="w-4 h-4" />
            </Button>
          </div>
        </div>
        {/* Iframe */}
        <iframe
          src={url}
          className="flex-1 w-full border-none"
          allow="autoplay; fullscreen; accelerometer; gyroscope"
          allowFullScreen
          title={title}
        />
      </motion.div>
    </AnimatePresence>
  );
}

import { useState } from 'react';
import { motion } from 'framer-motion';
import { ExternalLink, Maximize2, Monitor } from 'lucide-react';
import IframeViewer, { openCloaked } from './IframeViewer';
import { GetHubTabsOutputType } from 'zite-endpoints-sdk';

type HubTab = GetHubTabsOutputType['tabs'][0];
type HubItem = HubTab['items'][0];

interface Props {
  tab: HubTab;
}

export default function HubTabContent({ tab }: Props) {
  const [iframeItem, setIframeItem] = useState<HubItem | null>(null);

  if (iframeItem) {
    return (
      <IframeViewer
        url={iframeItem.url ?? ''}
        title={iframeItem.itemName ?? ''}
        emoji={iframeItem.emoji ?? undefined}
        onClose={() => setIframeItem(null)}
      />
    );
  }

  // Single item — auto-show as iframe with action buttons
  if (tab.tabType === 'Single' && tab.items.length > 0) {
    const item = tab.items[0];
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-64 gap-6 py-8">
        <div className="text-6xl">{item.emoji || tab.emoji || '🌐'}</div>
        <div className="text-center">
          <div className="text-2xl font-bold text-foreground mb-1">{item.itemName}</div>
          {item.description && <div className="text-muted-foreground text-sm">{item.description}</div>}
        </div>
        <div className="flex flex-wrap gap-3 justify-center">
          <ActionBtn icon={<Monitor className="w-4 h-4" />} label="Open as iframe" onClick={() => setIframeItem(item)} primary />
          <ActionBtn icon={<ExternalLink className="w-4 h-4" />} label="Cloaked new tab" onClick={() => openCloaked(item.url ?? '', item.itemName ?? '')} />
          <ActionBtn icon={<Maximize2 className="w-4 h-4" />} label="Fullscreen iframe" onClick={() => { setIframeItem(item); }} />
        </div>
      </div>
    );
  }

  // Multiple items — gaming/modern grid
  return (
    <div>
      <p className="text-muted-foreground text-sm mb-5">
        {tab.items.length} item{tab.items.length !== 1 ? 's' : ''} · Click a card to open
      </p>
      {tab.items.length === 0 ? (
        <div className="text-center py-14 text-muted-foreground text-sm">No items yet</div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {tab.items.map((item, i) => (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              <MultiItemCard item={item} onIframe={() => setIframeItem(item)} />
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

function MultiItemCard({ item, onIframe }: { item: HubItem; onIframe: () => void }) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      className="relative group rounded-xl border border-border bg-gradient-to-br from-muted/60 to-card overflow-hidden cursor-pointer transition-all duration-200 hover:border-primary/60 hover:shadow-lg hover:shadow-primary/10 hover:-translate-y-0.5"
    >
      {/* Glow effect */}
      <div className={`absolute inset-0 bg-primary/5 transition-opacity duration-300 ${hovered ? 'opacity-100' : 'opacity-0'}`} />

      <div className="relative p-5">
        <div className="text-4xl mb-3">{item.emoji || '🌐'}</div>
        <div className="font-bold text-foreground mb-0.5 text-base">{item.itemName}</div>
        {item.description && (
          <div className="text-xs text-muted-foreground mb-4 leading-relaxed">{item.description}</div>
        )}

        {/* Action row */}
        <div className={`flex gap-2 transition-all duration-200 ${hovered ? 'opacity-100 translate-y-0' : 'opacity-60 translate-y-1'}`}>
          <ActionPill icon={<Monitor className="w-3 h-3" />} label="Iframe" onClick={onIframe} />
          <ActionPill icon={<ExternalLink className="w-3 h-3" />} label="Cloaked" onClick={() => openCloaked(item.url ?? '', item.itemName ?? '')} />
          <ActionPill icon={<Maximize2 className="w-3 h-3" />} label="Full" onClick={onIframe} />
        </div>
      </div>
    </div>
  );
}

function ActionBtn({ icon, label, onClick, primary }: { icon: React.ReactNode; label: string; onClick: () => void; primary?: boolean }) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-150 border ${
        primary
          ? 'bg-primary text-primary-foreground border-primary hover:opacity-90'
          : 'bg-muted/40 text-foreground border-border hover:bg-primary/10 hover:border-primary/40'
      }`}
    >
      {icon} {label}
    </button>
  );
}

function ActionPill({ icon, label, onClick }: { icon: React.ReactNode; label: string; onClick: () => void }) {
  return (
    <button
      onClick={e => { e.stopPropagation(); onClick(); }}
      className="flex items-center gap-1 px-2 py-1 rounded-md text-xs font-medium bg-background/60 border border-border hover:bg-primary/20 hover:border-primary/40 hover:text-primary transition-colors"
    >
      {icon} {label}
    </button>
  );
}

import { useState, useEffect } from 'react';
import { getHubTabs, manageHubTab, manageHubItem, GetHubTabsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Plus, Trash2, Pencil, ChevronRight, ArrowLeft, Check, Layers, Link } from 'lucide-react';
import { toast } from 'sonner';
import { motion, AnimatePresence } from 'framer-motion';

type HubTab = GetHubTabsOutputType['tabs'][0];
type HubItem = HubTab['items'][0];

type View = 'tabs' | 'items' | 'editTab' | 'editItem';

export default function TabManager() {
  const [tabs, setTabs] = useState<HubTab[]>([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState<View>('tabs');
  const [selectedTab, setSelectedTab] = useState<HubTab | null>(null);
  const [editingTab, setEditingTab] = useState<Partial<HubTab> | null>(null);
  const [editingItem, setEditingItem] = useState<Partial<HubItem & { tabId?: string }> | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<{ type: 'tab' | 'item'; id: string; name: string } | null>(null);
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getHubTabs({});
      setTabs(res.tabs);
      if (selectedTab) {
        const updated = res.tabs.find(t => t.id === selectedTab.id);
        if (updated) setSelectedTab(updated);
      }
    } catch { toast.error('Failed to load tabs'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  // Save tab
  const saveTab = async () => {
    if (!editingTab?.tabName?.trim()) { toast.error('Tab name required'); return; }
    setSaving(true);
    try {
      if (editingTab.id) {
        await manageHubTab({ action: 'update', id: editingTab.id, tabName: editingTab.tabName, emoji: editingTab.emoji ?? '', tabType: (editingTab.tabType as 'Single' | 'Multiple') ?? 'Multiple', sortOrder: editingTab.sortOrder ?? 0 });
        toast.success('Tab updated');
      } else {
        await manageHubTab({ action: 'create', tabName: editingTab.tabName, emoji: editingTab.emoji ?? '', tabType: (editingTab.tabType as 'Single' | 'Multiple') ?? 'Multiple', sortOrder: editingTab.sortOrder ?? 0 });
        toast.success('Tab created');
      }
      await load();
      setView('tabs');
      setEditingTab(null);
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSaving(false);
  };

  // Save item
  const saveItem = async () => {
    if (!editingItem?.itemName?.trim()) { toast.error('Item name required'); return; }
    if (!editingItem?.url?.trim()) { toast.error('URL required'); return; }
    setSaving(true);
    try {
      if (editingItem.id) {
        await manageHubItem({ action: 'update', id: editingItem.id, itemName: editingItem.itemName, url: editingItem.url, emoji: editingItem.emoji ?? '', description: editingItem.description ?? '' });
        toast.success('Item updated');
      } else {
        await manageHubItem({ action: 'create', tabId: selectedTab?.id, itemName: editingItem.itemName, url: editingItem.url, emoji: editingItem.emoji ?? '', description: editingItem.description ?? '' });
        toast.success('Item added');
      }
      await load();
      setView('items');
      setEditingItem(null);
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setSaving(false);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      if (deleteTarget.type === 'tab') {
        await manageHubTab({ action: 'delete', id: deleteTarget.id });
        setSelectedTab(null);
        setView('tabs');
        toast.success('Tab deleted');
      } else {
        await manageHubItem({ action: 'delete', id: deleteTarget.id });
        toast.success('Item deleted');
      }
      await load();
    } catch (e: any) { toast.error(e?.message ?? 'Failed to delete'); }
    setDeleteTarget(null);
  };

  const renderTabList = () => (
    <div className="space-y-3">
      <div className="flex justify-between items-center">
        <span className="text-sm text-muted-foreground">{tabs.length} custom tab{tabs.length !== 1 ? 's' : ''}</span>
        <Button size="sm" onClick={() => { setEditingTab({ tabType: 'Multiple', sortOrder: tabs.length }); setView('editTab'); }}>
          <Plus className="w-4 h-4 mr-1" /> New Tab
        </Button>
      </div>
      {loading ? (
        <div className="space-y-2">{[...Array(3)].map((_, i) => <div key={i} className="h-14 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : tabs.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No custom tabs yet. Create one to get started.</div>
      ) : (
        <div className="space-y-2 max-h-80 overflow-y-auto pr-1">
          {tabs.map(tab => (
            <div key={tab.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3 group">
              <span className="text-xl">{tab.emoji || '📋'}</span>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground">{tab.tabName}</div>
                <div className="text-xs text-muted-foreground">{tab.tabType} · {tab.items?.length ?? 0} item{(tab.items?.length ?? 0) !== 1 ? 's' : ''}</div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <Button variant="ghost" size="sm" className="h-7 text-xs gap-1" onClick={() => { setSelectedTab(tab); setView('items'); }}>
                  Items <ChevronRight className="w-3 h-3" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setEditingTab(tab); setView('editTab'); }}>
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget({ type: 'tab', id: tab.id, name: tab.tabName ?? '' })}>
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderItemList = () => (
    <div className="space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <Button variant="ghost" size="sm" onClick={() => setView('tabs')}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{selectedTab?.emoji} {selectedTab?.tabName}</span>
        <span className="text-xs text-muted-foreground px-2 py-0.5 rounded-full bg-muted border border-border">{selectedTab?.tabType}</span>
      </div>
      <div className="flex justify-end">
        <Button size="sm" onClick={() => { setEditingItem({}); setView('editItem'); }}>
          <Plus className="w-4 h-4 mr-1" /> Add Item
        </Button>
      </div>
      {(selectedTab?.items?.length ?? 0) === 0 ? (
        <div className="text-center py-8 text-muted-foreground text-sm">No items yet</div>
      ) : (
        <div className="space-y-2 max-h-72 overflow-y-auto pr-1">
          {selectedTab?.items?.map(item => (
            <div key={item.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3">
              <span className="text-lg">{item.emoji || '🔗'}</span>
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground">{item.itemName}</div>
                <div className="text-xs text-muted-foreground truncate">{item.url}</div>
              </div>
              <div className="flex gap-1 shrink-0">
                <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => { setEditingItem(item); setView('editItem'); }}>
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget({ type: 'item', id: item.id, name: item.itemName ?? '' })}>
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );

  const renderEditTab = () => (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={() => { setView('tabs'); setEditingTab(null); }}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{editingTab?.id ? 'Edit Tab' : 'New Tab'}</span>
      </div>
      <div className="grid grid-cols-4 gap-2">
        <Input placeholder="Emoji" value={editingTab?.emoji ?? ''} onChange={e => setEditingTab(p => ({ ...p, emoji: e.target.value }))} className="col-span-1" />
        <Input placeholder="Tab name" value={editingTab?.tabName ?? ''} onChange={e => setEditingTab(p => ({ ...p, tabName: e.target.value }))} className="col-span-3" />
      </div>
      <div className="space-y-1">
        <label className="text-xs text-muted-foreground font-medium">Tab Type</label>
        <Select value={editingTab?.tabType ?? 'Multiple'} onValueChange={v => setEditingTab(p => ({ ...p, tabType: v }))}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="Multiple">Multiple Items — grid layout</SelectItem>
            <SelectItem value="Single">Single Item — direct launch</SelectItem>
          </SelectContent>
        </Select>
        <p className="text-xs text-muted-foreground pt-1">
          {editingTab?.tabType === 'Single'
            ? 'Only the first item is used. It opens directly with iframe/fullscreen/cloaked options.'
            : 'All items shown as a gaming-style grid. Each card has its own launch options.'}
        </p>
      </div>
      <Input placeholder="Sort order (0 = first)" type="number" value={editingTab?.sortOrder ?? 0} onChange={e => setEditingTab(p => ({ ...p, sortOrder: Number(e.target.value) }))} />
      <div className="flex gap-2">
        <Button onClick={saveTab} disabled={saving}><Check className="w-4 h-4 mr-1" />{saving ? 'Saving...' : 'Save Tab'}</Button>
        <Button variant="outline" onClick={() => { setView('tabs'); setEditingTab(null); }}>Cancel</Button>
      </div>
    </div>
  );

  const renderEditItem = () => (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="sm" onClick={() => { setView('items'); setEditingItem(null); }}><ArrowLeft className="w-4 h-4" /></Button>
        <span className="font-semibold text-foreground">{editingItem?.id ? 'Edit Item' : 'New Item'}</span>
      </div>
      <div className="grid grid-cols-4 gap-2">
        <Input placeholder="Emoji" value={editingItem?.emoji ?? ''} onChange={e => setEditingItem(p => ({ ...p, emoji: e.target.value }))} className="col-span-1" />
        <Input placeholder="Item name" value={editingItem?.itemName ?? ''} onChange={e => setEditingItem(p => ({ ...p, itemName: e.target.value }))} className="col-span-3" />
      </div>
      <div className="relative">
        <Link className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
        <Input placeholder="https://example.com" value={editingItem?.url ?? ''} onChange={e => setEditingItem(p => ({ ...p, url: e.target.value }))} className="pl-8" />
      </div>
      <Input placeholder="Short description (optional)" value={editingItem?.description ?? ''} onChange={e => setEditingItem(p => ({ ...p, description: e.target.value }))} />
      <div className="flex gap-2">
        <Button onClick={saveItem} disabled={saving}><Check className="w-4 h-4 mr-1" />{saving ? 'Saving...' : 'Save Item'}</Button>
        <Button variant="outline" onClick={() => { setView('items'); setEditingItem(null); }}>Cancel</Button>
      </div>
    </div>
  );

  return (
    <div>
      <div className="flex items-center gap-2 mb-4">
        <Layers className="w-4 h-4 text-primary" />
        <span className="text-sm font-medium text-foreground">Custom Hub Tabs</span>
        <span className="text-xs text-muted-foreground">— visible to all hub visitors</span>
      </div>
      <AnimatePresence mode="wait">
        <motion.div key={view} initial={{ opacity: 0, x: 8 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -8 }} transition={{ duration: 0.12 }}>
          {view === 'tabs' && renderTabList()}
          {view === 'items' && renderItemList()}
          {view === 'editTab' && renderEditTab()}
          {view === 'editItem' && renderEditItem()}
        </motion.div>
      </AnimatePresence>

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {deleteTarget?.type === 'tab' ? 'Tab' : 'Item'}</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete "<strong>{deleteTarget?.name}</strong>"?
              {deleteTarget?.type === 'tab' && ' All items in this tab will also be deleted.'}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

