import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Gamepad2, Globe, Shield, ExternalLink, Zap, ChevronRight, LogIn, Users, Megaphone, Settings, BarChart3, Layers, RefreshCw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from 'zite-auth-sdk';
import { checkAdmin, getHubTabs, GetHubTabsOutputType } from 'zite-endpoints-sdk';
import UserManager from './admin/UserManager';
import AnnouncementManager from './admin/AnnouncementManager';
import SiteControls from './admin/SiteControls';
import TabManager from './admin/TabManager';
import HubTabContent from './HubTabContent';
import { Toaster } from '@/components/ui/sonner';

type HubTab = GetHubTabsOutputType['tabs'][0];

const GAMES = [
  { name: 'Slope', url: 'https://slope-game.github.io/', emoji: '🎿', desc: 'Roll a ball down a never-ending slope' },
  { name: '1v1.LOL', url: 'https://1v1.lol', emoji: '🏗️', desc: 'Build & battle shooter' },
  { name: 'Shell Shockers', url: 'https://shellshock.io', emoji: '🥚', desc: 'Egg-based FPS game' },
  { name: 'Krunker.io', url: 'https://krunker.io', emoji: '🔫', desc: 'Fast-paced browser FPS' },
  { name: 'Agar.io', url: 'https://agar.io', emoji: '🔵', desc: 'Eat cells and grow big' },
  { name: 'Slither.io', url: 'https://slither.io', emoji: '🐍', desc: 'Classic snake multiplayer' },
  { name: 'Paper.io 2', url: 'https://paper-io.com', emoji: '📄', desc: 'Claim territory on the map' },
  { name: 'Geometry Dash', url: 'https://geometrydash.io', emoji: '🔷', desc: 'Rhythm-based platformer' },
  { name: 'Drift Boss', url: 'https://driftboss.io', emoji: '🚗', desc: 'Drift around corners endlessly' },
  { name: 'Cookie Clicker', url: 'https://orteil.dashnet.org/cookieclicker/', emoji: '🍪', desc: 'Idle clicking game' },
  { name: 'Wordle', url: 'https://www.nytimes.com/games/wordle/index.html', emoji: '🟩', desc: 'Guess the 5-letter word' },
  { name: 'Pac-Man', url: 'https://freepacman.org', emoji: '👾', desc: 'Classic arcade game' },
];

const PROXIES = [
  { name: 'Ultraviolet', url: 'https://uv.arethun.net', emoji: '🌐', desc: 'Popular web proxy service' },
  { name: 'Titanium Network', url: 'https://titaniumnetwork.org', emoji: '⚡', desc: 'Open-source proxy network' },
  { name: 'Holy Unblocker', url: 'https://holyubofficial.net', emoji: '✝️', desc: 'Reliable unblocking proxy' },
  { name: 'Interstellar', url: 'https://interstellar.arethun.net', emoji: '🚀', desc: 'Fast, modern proxy' },
  { name: 'Nebula Proxy', url: 'https://nebulaproxy.io', emoji: '🌌', desc: 'Clean and simple proxy' },
  { name: '3kh0', url: 'https://3kh0.github.io', emoji: '🎮', desc: 'Games & proxy hub' },
];

type AdminSubTab = 'overview' | 'users' | 'announcements' | 'settings' | 'tabs';

export default function SecretHub({ onClose }: { onClose: () => void }) {
  const [activeTab, setActiveTab] = useState<string>('games');
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [isAdmin, setIsAdmin] = useState(false);
  const [adminChecked, setAdminChecked] = useState(false);
  const [adminSubTab, setAdminSubTab] = useState<AdminSubTab>('overview');
  const [customTabs, setCustomTabs] = useState<HubTab[]>([]);
  const [tabsLoading, setTabsLoading] = useState(true);

  useEffect(() => {
    if (!isLoading && user) {
      checkAdmin({}).then(res => { setIsAdmin(res.isAdmin); setAdminChecked(true); }).catch(() => setAdminChecked(true));
    } else if (!isLoading) {
      setAdminChecked(true);
    }
  }, [user, isLoading]);

  const loadCustomTabs = async () => {
    setTabsLoading(true);
    try {
      const res = await getHubTabs({});
      setCustomTabs(res.tabs);
    } catch {}
    setTabsLoading(false);
  };

  useEffect(() => { loadCustomTabs(); }, []);

  const builtInTabs = [
    { id: 'games', label: 'Games', icon: Gamepad2 },
    { id: 'proxies', label: 'Proxies', icon: Globe },
  ];
  const allDisplayTabs = [...builtInTabs, ...customTabs.map(t => ({ id: `custom_${t.id}`, label: t.tabName ?? 'Tab', icon: null, emoji: t.emoji }))];

  const activeCustomTab = activeTab.startsWith('custom_')
    ? customTabs.find(t => `custom_${t.id}` === activeTab)
    : null;

  return (
    <>
      <Toaster />
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-[9999] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4"
      >
        <motion.div
          initial={{ scale: 0.9, y: 20 }}
          animate={{ scale: 1, y: 0 }}
          exit={{ scale: 0.9, y: 20 }}
          className="bg-card border border-border rounded-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col shadow-2xl"
        >
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-muted/30 shrink-0">
            <div className="flex items-center gap-2">
              <Zap className="w-5 h-5 text-primary" />
              <span className="font-bold text-foreground text-lg">Genizy Hub</span>
              <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium">SECRET</span>
              {isAdmin && <span className="text-xs bg-destructive/20 text-destructive border border-destructive/30 px-2 py-0.5 rounded-full font-medium">ADMIN</span>}
            </div>
            <div className="flex items-center gap-2">
              <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground" title="Refresh tabs" onClick={loadCustomTabs}>
                <RefreshCw className={`w-3.5 h-3.5 ${tabsLoading ? 'animate-spin' : ''}`} />
              </Button>
              {user && <span className="text-xs text-muted-foreground hidden sm:block">{user.email}</span>}
              <button onClick={onClose} className="text-muted-foreground hover:text-foreground transition-colors">
                <X className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Tab Bar */}
          <div className="flex border-b border-border overflow-x-auto shrink-0 scrollbar-none">
            {allDisplayTabs.map(t => (
              <button
                key={t.id}
                onClick={() => setActiveTab(t.id)}
                className={`flex items-center gap-2 px-5 py-3 text-sm font-medium transition-colors border-b-2 whitespace-nowrap shrink-0 ${
                  activeTab === t.id ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                {'icon' in t && t.icon ? <t.icon className="w-4 h-4" /> : <span className="text-sm">{(t as any).emoji || '📋'}</span>}
                {t.label}
              </button>
            ))}
            {/* Admin tab always last */}
            <button
              onClick={() => setActiveTab('admin')}
              className={`flex items-center gap-2 px-5 py-3 text-sm font-medium transition-colors border-b-2 whitespace-nowrap shrink-0 ml-auto ${
                activeTab === 'admin' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              <Shield className="w-4 h-4" />
              Admin
              {isAdmin && <span className="w-2 h-2 rounded-full bg-destructive ml-0.5" />}
            </button>
          </div>

          {/* Content */}
          <div className="flex-1 overflow-y-auto p-6">
            <AnimatePresence mode="wait">
              <motion.div key={activeTab} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.12 }}>

                {activeTab === 'games' && (
                  <div>
                    <p className="text-muted-foreground text-sm mb-4">Click any game to open it in a new tab.</p>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                      {GAMES.map(game => (
                        <a key={game.name} href={game.url} target="_blank" rel="noopener noreferrer"
                          className="group bg-muted/40 hover:bg-primary/10 border border-border hover:border-primary/50 rounded-xl p-4 transition-all duration-200 hover:-translate-y-0.5">
                          <div className="text-3xl mb-2">{game.emoji}</div>
                          <div className="font-semibold text-sm text-foreground group-hover:text-primary transition-colors flex items-center gap-1">
                            {game.name} <ExternalLink className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                          </div>
                          <div className="text-xs text-muted-foreground mt-0.5 leading-snug">{game.desc}</div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                {activeTab === 'proxies' && (
                  <div>
                    <p className="text-muted-foreground text-sm mb-4">Access web proxies to browse freely. Links open in a new tab.</p>
                    <div className="space-y-3">
                      {PROXIES.map(proxy => (
                        <a key={proxy.name} href={proxy.url} target="_blank" rel="noopener noreferrer"
                          className="group flex items-center justify-between bg-muted/40 hover:bg-primary/10 border border-border hover:border-primary/50 rounded-xl px-5 py-4 transition-all duration-200">
                          <div className="flex items-center gap-4">
                            <span className="text-2xl">{proxy.emoji}</span>
                            <div>
                              <div className="font-semibold text-foreground group-hover:text-primary transition-colors">{proxy.name}</div>
                              <div className="text-xs text-muted-foreground">{proxy.desc}</div>
                            </div>
                          </div>
                          <div className="flex items-center gap-1 text-xs text-muted-foreground group-hover:text-primary transition-colors">
                            Open <ChevronRight className="w-4 h-4" />
                          </div>
                        </a>
                      ))}
                    </div>
                  </div>
                )}

                {activeCustomTab && <HubTabContent tab={activeCustomTab} />}

                {activeTab === 'admin' && (
                  <AdminSection
                    user={user} isAdmin={isAdmin} adminChecked={adminChecked}
                    isLoading={isLoading} loginWithRedirect={loginWithRedirect}
                    adminSubTab={adminSubTab} setAdminSubTab={setAdminSubTab}
                    onTabsChanged={loadCustomTabs}
                  />
                )}

              </motion.div>
            </AnimatePresence>
          </div>
        </motion.div>
      </motion.div>
    </>
  );
}

function AdminSection({ user, isAdmin, adminChecked, isLoading, loginWithRedirect, adminSubTab, setAdminSubTab, onTabsChanged }: {
  user: any; isAdmin: boolean; adminChecked: boolean; isLoading: boolean;
  loginWithRedirect: (opts?: any) => void; adminSubTab: AdminSubTab; setAdminSubTab: (t: AdminSubTab) => void;
  onTabsChanged: () => void;
}) {
  if (isLoading || !adminChecked) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-3">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
        <p className="text-sm text-muted-foreground">Checking access...</p>
      </div>
    );
  }
  if (!user) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Admin Access</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">Sign in with an admin account to access this panel.</p>
        <Button onClick={() => loginWithRedirect({ redirectUrl: window.location.href })} className="flex items-center gap-2">
          <LogIn className="w-4 h-4" /> Sign In
        </Button>
      </div>
    );
  }
  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center py-16 gap-4">
        <Shield className="w-12 h-12 text-muted-foreground" />
        <h3 className="text-xl font-bold text-foreground">Access Denied</h3>
        <p className="text-muted-foreground text-sm text-center max-w-xs">
          <strong>{user.email}</strong> does not have admin privileges.
        </p>
      </div>
    );
  }

  const subTabs = [
    { id: 'overview', label: 'Overview', icon: BarChart3 },
    { id: 'users', label: 'Users', icon: Users },
    { id: 'announcements', label: 'Announcements', icon: Megaphone },
    { id: 'tabs', label: 'Hub Tabs', icon: Layers },
    { id: 'settings', label: 'Site Controls', icon: Settings },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2 text-green-400 text-sm font-medium">
        <Shield className="w-4 h-4" /> Admin: {user.email}
      </div>
      <div className="flex gap-1 bg-muted/40 p-1 rounded-xl flex-wrap">
        {subTabs.map(t => (
          <button key={t.id} onClick={() => setAdminSubTab(t.id as AdminSubTab)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${adminSubTab === t.id ? 'bg-card text-foreground shadow-sm' : 'text-muted-foreground hover:text-foreground'}`}>
            <t.icon className="w-3.5 h-3.5" />
            {t.label}
          </button>
        ))}
      </div>
      <AnimatePresence mode="wait">
        <motion.div key={adminSubTab} initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.12 }}>
          {adminSubTab === 'overview' && <AdminOverview />}
          {adminSubTab === 'users' && <UserManager />}
          {adminSubTab === 'announcements' && <AnnouncementManager />}
          {adminSubTab === 'tabs' && <TabManager />}
          {adminSubTab === 'settings' && <SiteControls />}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

function AdminOverview() {
  const stats = [
    { label: 'Subjects', value: '8', icon: '📚' },
