                  <div>
                    <p className="text-muted-foreground text-sm mb-4">{PROXIES.length} proxies — choose how to launch</p>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {PROXIES.map(p => <LaunchCard key={p.name} name={p.name} url={p.url} emoji={p.emoji} desc={p.desc} onIframe={() => setIframeTarget({ url: p.url, name: p.name, emoji: p.emoji })} wide />)}
