import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Search, Trash2, ShieldCheck, UserX, RefreshCw, Crown, Shield, User, UserCheck } from 'lucide-react';
import { toast } from 'sonner';

type UserRow = GetUsersOutputType['users'][0];

type RoleName = 'Owner' | 'Admin' | 'Moderator' | 'User' | 'Banned';

const ROLE_META: Record<string, { color: string; icon: React.ReactNode }> = {
  Owner: { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', icon: <Crown className="w-3 h-3" /> },
  Admin: { color: 'bg-primary/20 text-primary border-primary/30', icon: <Shield className="w-3 h-3" /> },
  Moderator: { color: 'bg-purple-500/20 text-purple-400 border-purple-500/30', icon: <ShieldCheck className="w-3 h-3" /> },
  User: { color: 'bg-muted text-muted-foreground border-border', icon: <User className="w-3 h-3" /> },
  Banned: { color: 'bg-destructive/20 text-destructive border-destructive/30', icon: <UserX className="w-3 h-3" /> },
};

function roleRank(role?: string) {
  switch (role) { case 'Owner': return 4; case 'Admin': return 3; case 'Moderator': return 2; case 'User': return 1; default: return 0; }
}

function getAssignableRoles(myRole?: string): RoleName[] {
  switch (myRole) {
    case 'Owner': return ['Admin', 'Moderator', 'User', 'Banned'];
    case 'Admin': return ['Moderator', 'User', 'Banned'];
    case 'Moderator': return ['User', 'Banned'];
    default: return [];
  }
}

export default function UserManager({ myRole }: { myRole?: string }) {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('all');
  const [deleteTarget, setDeleteTarget] = useState<UserRow | null>(null);
  const [updating, setUpdating] = useState<string | null>(null);

  const load = async (s = search, r = roleFilter) => {
    setLoading(true);
    try { const res = await getUsers({ search: s, roleFilter: r }); setUsers(res.users); }
    catch { toast.error('Failed to load users'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleRoleChange = async (userId: string, role: RoleName) => {
    setUpdating(userId);
    try {
      await updateUser({ userId, role });
      setUsers(prev => prev.map(u => u.id === userId ? { ...u, role } : u));
      toast.success('Role updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setUpdating(null);
  };

  const handleToggleActive = async (user: UserRow) => {
    setUpdating(user.id);
    try {
      await updateUser({ userId: user.id, isActive: !user.isActive });
      setUsers(prev => prev.map(u => u.id === user.id ? { ...u, isActive: !u.isActive } : u));
      toast.success('Status updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setUpdating(null);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      await deleteUser({ userId: deleteTarget.id });
      setUsers(prev => prev.filter(u => u.id !== deleteTarget.id));
      toast.success('User deleted');
    } catch (e: any) { toast.error(e?.message ?? 'Failed'); }
    setDeleteTarget(null);
  };

  const assignableRoles = getAssignableRoles(myRole);
  const canDelete = roleRank(myRole) >= 3;

  return (
    <div className="space-y-4">
      {/* Permission hint */}
      <div className="flex items-center gap-2 text-xs text-muted-foreground bg-muted/30 rounded-lg px-3 py-2 border border-border">
        {myRole === 'Owner' && <><Crown className="w-3.5 h-3.5 text-yellow-400" /> Owner — full user management, including admins</>}
        {myRole === 'Admin' && <><Shield className="w-3.5 h-3.5 text-primary" /> Admin — manage Moderators and below</>}
        {myRole === 'Moderator' && <><ShieldCheck className="w-3.5 h-3.5 text-purple-400" /> Moderator — can ban/unban regular users only</>}
      </div>

      <div className="flex flex-col sm:flex-row gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input placeholder="Search users..." className="pl-9" value={search} onChange={e => { setSearch(e.target.value); load(e.target.value, roleFilter); }} />
        </div>
        <Select value={roleFilter} onValueChange={v => { setRoleFilter(v); load(search, v); }}>
          <SelectTrigger className="w-36"><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Roles</SelectItem>
            <SelectItem value="Owner">Owner</SelectItem>
            <SelectItem value="Admin">Admin</SelectItem>
            <SelectItem value="Moderator">Moderator</SelectItem>
            <SelectItem value="User">User</SelectItem>
            <SelectItem value="Banned">Banned</SelectItem>
          </SelectContent>
        </Select>
        <Button variant="outline" size="icon" onClick={() => load()}><RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /></Button>
      </div>

      <div className="text-xs text-muted-foreground">{users.length} user{users.length !== 1 ? 's' : ''}</div>

      {loading ? (
        <div className="space-y-2">{[...Array(4)].map((_, i) => <div key={i} className="h-14 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : users.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No users found</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {users.map(user => {
            const meta = ROLE_META[user.role ?? 'User'] ?? ROLE_META.User;
            const targetRank = roleRank(user.role);
            const myRank = roleRank(myRole);
            const canModify = targetRank < myRank;
            return (
              <div key={user.id} className="flex items-center gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3">
                <div className="w-8 h-8 rounded-full bg-primary/20 flex items-center justify-center shrink-0">
                  {meta.icon}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-sm text-foreground truncate">
                    {user.firstName || user.lastName ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() : user.email}
                  </div>
                  <div className="text-xs text-muted-foreground truncate">{user.email}</div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <span className={`text-xs px-2 py-0.5 rounded-full border font-medium flex items-center gap-1 ${meta.color}`}>
                    {meta.icon}{user.role ?? 'User'}
                  </span>
                  {canModify && assignableRoles.length > 0 && (
                    <Select value={user.role ?? 'User'} onValueChange={v => handleRoleChange(user.id, v as RoleName)} disabled={updating === user.id}>
                      <SelectTrigger className="h-7 w-28 text-xs"><SelectValue /></SelectTrigger>
                      <SelectContent>
                        {assignableRoles.map(r => <SelectItem key={r} value={r}>{r}</SelectItem>)}
                      </SelectContent>
                    </Select>
                  )}
                  {canModify && (
                    <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => handleToggleActive(user)} disabled={updating === user.id} title={user.isActive ? 'Deactivate' : 'Activate'}>
                      {user.isActive !== false ? <UserCheck className="w-3.5 h-3.5 text-primary" /> : <UserX className="w-3.5 h-3.5 text-muted-foreground" />}
                    </Button>
                  )}
                  {canDelete && canModify && (
                    <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget(user)} disabled={updating === user.id}>
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete User</AlertDialogTitle>
            <AlertDialogDescription>Permanently delete <strong>{deleteTarget?.email}</strong>? This cannot be undone.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { getAuditLog, GetAuditLogOutputType } from 'zite-endpoints-sdk';
import { RefreshCw, Crown, Shield, ShieldCheck, ClipboardList } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';

type Entry = GetAuditLogOutputType['entries'][0];

const ROLE_ICON: Record<string, React.ReactNode> = {
  Owner: <Crown className="w-3 h-3 text-yellow-400" />,
  Admin: <Shield className="w-3 h-3 text-primary" />,
  Moderator: <ShieldCheck className="w-3 h-3 text-purple-400" />,
};

function formatDate(iso?: string) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString();
}

export default function AuditLogViewer() {
  const [entries, setEntries] = useState<Entry[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try { const res = await getAuditLog({ limit: 100 }); setEntries(res.entries); }
    catch { toast.error('Failed to load audit log'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <ClipboardList className="w-4 h-4" /> {entries.length} log entries
        </div>
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={load}>
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">{[...Array(5)].map((_, i) => <div key={i} className="h-12 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : entries.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No audit log entries yet</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {entries.map(entry => (
            <div key={entry.id} className="bg-muted/30 border border-border rounded-lg px-4 py-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-0.5">
                    <span className="flex items-center gap-1 text-xs font-medium text-foreground">
                      {ROLE_ICON[entry.roleLevel ?? ''] ?? null}
                      {entry.performedBy}
                    </span>
                    <span className="text-xs text-muted-foreground">→</span>
                    <span className="text-xs text-foreground/70">{entry.targetUser}</span>
                  </div>
                  <div className="text-xs font-semibold text-primary">{entry.action}</div>
                  {entry.details && <div className="text-xs text-muted-foreground mt-0.5 truncate">{entry.details}</div>}
                </div>
                <div className="text-xs text-muted-foreground whitespace-nowrap shrink-0">{formatDate(entry.timestamp)}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

