import { z } from 'zod';
import { createEndpoint, HubItems, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create, update, or delete a hub item — admin only',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['create', 'update', 'delete']),
    id: z.string().optional(),
    tabId: z.string().optional(),
    itemName: z.string().optional(),
    url: z.string().optional(),
    emoji: z.string().optional(),
    description: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.string().optional() }),
  execute: async ({ input, context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    if (caller?.role !== 'Admin') throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin only' });

    if (input.action === 'create') {
      const rec = await HubItems.create({
        record: { itemName: input.itemName, url: input.url, emoji: input.emoji, description: input.description, tabId: input.tabId },
      });
      return { success: true, id: rec.id };
    }
    if (input.action === 'update' && input.id) {
      await HubItems.update({ id: input.id, record: { itemName: input.itemName, url: input.url, emoji: input.emoji, description: input.description } });
      return { success: true, id: input.id };
    }
    if (input.action === 'delete' && input.id) {
      await HubItems.delete({ id: input.id });
      return { success: true };
    }
    throw new ZiteError({ code: 'BAD_REQUEST', message: 'Invalid action' });
  },
});

