import { z } from 'zod';
import { createEndpoint, Announcements, Users, ZiteError } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Get all announcements - admin only',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    announcements: z.array(z.object({
      id: z.string(),
      title: z.string().optional(),
      message: z.string().optional(),
      status: z.string().optional(),
      postedAt: z.string().optional(),
      postedBy: z.string().optional(),
    })),
  }),
  execute: async ({ context }) => {
    const callerRecord = await Users.findOne({ id: context.user.id });
    if (callerRecord?.role !== 'Admin') {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Admin access required' });
    }
    const { records } = await Announcements.findAll({ limit: 100 });
    return {
      announcements: records.map(a => ({
        id: a.id,
        title: a.title,
        message: a.message,
        status: a.status,
        postedAt: a.postedAt,
        postedBy: a.postedBy,
      })),
    };
  },
});

import { useState, useEffect } from 'react';
import { getAnnouncements, manageAnnouncement, GetAnnouncementsOutputType } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { Plus, Trash2, Pencil, Megaphone, Check } from 'lucide-react';
import { toast } from 'sonner';

type Ann = GetAnnouncementsOutputType['announcements'][0];

const STATUS_COLORS: Record<string, string> = {
  Active: 'text-green-400 bg-green-400/10 border-green-400/20',
  Draft: 'text-yellow-400 bg-yellow-400/10 border-yellow-400/20',
  Archived: 'text-muted-foreground bg-muted/40 border-border',
};

export default function AnnouncementManager() {
  const [announcements, setAnnouncements] = useState<Ann[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<Partial<Ann> | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<Ann | null>(null);
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getAnnouncements({});
      setAnnouncements(res.announcements);
    } catch { toast.error('Failed to load announcements'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const handleSave = async () => {
    if (!editing?.title?.trim()) { toast.error('Title is required'); return; }
    setSaving(true);
    try {
      if (editing.id) {
        await manageAnnouncement({ action: 'update', id: editing.id, title: editing.title, message: editing.message ?? '', status: (editing.status as any) ?? 'Draft' });
        setAnnouncements(prev => prev.map(a => a.id === editing.id ? { ...a, ...editing } : a));
        toast.success('Announcement updated');
      } else {
        const res = await manageAnnouncement({ action: 'create', title: editing.title, message: editing.message ?? '', status: (editing.status as any) ?? 'Draft' });
        await load();
        toast.success('Announcement created');
      }
      setEditing(null);
    } catch (e: any) { toast.error(e?.message ?? 'Failed to save'); }
    setSaving(false);
  };

  const handleDelete = async () => {
    if (!deleteTarget) return;
    try {
      await manageAnnouncement({ action: 'delete', id: deleteTarget.id });
      setAnnouncements(prev => prev.filter(a => a.id !== deleteTarget.id));
      toast.success('Deleted');
    } catch (e: any) { toast.error(e?.message ?? 'Failed to delete'); }
    setDeleteTarget(null);
  };

  if (editing !== null) {
    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2 mb-2">
          <Button variant="ghost" size="sm" onClick={() => setEditing(null)}>← Back</Button>
          <span className="font-semibold text-foreground">{editing.id ? 'Edit Announcement' : 'New Announcement'}</span>
        </div>
        <Input placeholder="Title" value={editing.title ?? ''} onChange={e => setEditing(prev => ({ ...prev, title: e.target.value }))} />
        <textarea
          className="w-full bg-background border border-border rounded-lg p-3 text-sm text-foreground resize-none focus:outline-none focus:ring-2 focus:ring-primary/50 h-28"
          placeholder="Message..."
          value={editing.message ?? ''}
          onChange={e => setEditing(prev => ({ ...prev, message: e.target.value }))}
        />
        <Select value={editing.status ?? 'Draft'} onValueChange={v => setEditing(prev => ({ ...prev, status: v }))}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="Active">Active</SelectItem>
            <SelectItem value="Draft">Draft</SelectItem>
            <SelectItem value="Archived">Archived</SelectItem>
          </SelectContent>
        </Select>
        <div className="flex gap-2">
          <Button onClick={handleSave} disabled={saving} className="flex items-center gap-2">
            <Check className="w-4 h-4" /> {saving ? 'Saving...' : 'Save'}
          </Button>
          <Button variant="outline" onClick={() => setEditing(null)}>Cancel</Button>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <span className="text-sm text-muted-foreground">{announcements.length} announcement{announcements.length !== 1 ? 's' : ''}</span>
        <Button size="sm" onClick={() => setEditing({ status: 'Draft' })} className="flex items-center gap-2">
          <Plus className="w-4 h-4" /> New
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">{[...Array(3)].map((_, i) => <div key={i} className="h-16 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : announcements.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No announcements yet</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {announcements.map(ann => (
            <div key={ann.id} className="flex items-start gap-3 bg-muted/30 border border-border rounded-lg px-4 py-3">
              <Megaphone className="w-4 h-4 text-primary mt-0.5 shrink-0" />
              <div className="flex-1 min-w-0">
                <div className="font-medium text-sm text-foreground">{ann.title}</div>
                {ann.message && <div className="text-xs text-muted-foreground truncate mt-0.5">{ann.message}</div>}
                <div className="flex items-center gap-2 mt-1">
                  <span className={`text-xs px-2 py-0.5 rounded-full border font-medium ${STATUS_COLORS[ann.status ?? 'Draft'] ?? STATUS_COLORS.Draft}`}>
                    {ann.status ?? 'Draft'}
                  </span>
                  {ann.postedBy && <span className="text-xs text-muted-foreground">by {ann.postedBy}</span>}
                </div>
              </div>
              <div className="flex gap-1 shrink-0">
                <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setEditing(ann)}>
                  <Pencil className="w-3.5 h-3.5" />
                </Button>
                <Button variant="ghost" size="icon" className="h-7 w-7 hover:text-destructive" onClick={() => setDeleteTarget(ann)}>
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Announcement</AlertDialogTitle>
            <AlertDialogDescription>Delete "<strong>{deleteTarget?.title}</strong>"? This cannot be undone.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { z } from 'zod';
import { createEndpoint, Users } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Check the current user role and permissions',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    role: z.string(),
    isOwner: z.boolean(),
    isAdmin: z.boolean(),
    isModerator: z.boolean(),
    canManageUsers: z.boolean(),
    canManageAdmins: z.boolean(),
    canManageSite: z.boolean(),
    canManageHub: z.boolean(),
    canViewAuditLog: z.boolean(),
    user: z.object({
      id: z.string(),
      email: z.string(),
