import { useState, useEffect } from 'react';
import { getAuditLog, GetAuditLogOutputType } from 'zite-endpoints-sdk';
import { RefreshCw, Crown, Shield, ShieldCheck, ClipboardList } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';

type Entry = GetAuditLogOutputType['entries'][0];

const ROLE_ICON: Record<string, React.ReactNode> = {
  Owner: <Crown className="w-3 h-3 text-yellow-400" />,
  Admin: <Shield className="w-3 h-3 text-primary" />,
  Moderator: <ShieldCheck className="w-3 h-3 text-purple-400" />,
};

function formatDate(iso?: string) {
  if (!iso) return '—';
  return new Date(iso).toLocaleString();
}

export default function AuditLogViewer() {
  const [entries, setEntries] = useState<Entry[]>([]);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    setLoading(true);
    try { const res = await getAuditLog({ limit: 100 }); setEntries(res.entries); }
    catch { toast.error('Failed to load audit log'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <ClipboardList className="w-4 h-4" /> {entries.length} log entries
        </div>
        <Button variant="ghost" size="icon" className="h-7 w-7" onClick={load}>
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {loading ? (
        <div className="space-y-2">{[...Array(5)].map((_, i) => <div key={i} className="h-12 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : entries.length === 0 ? (
        <div className="text-center py-10 text-muted-foreground text-sm">No audit log entries yet</div>
      ) : (
        <div className="space-y-2 max-h-96 overflow-y-auto pr-1">
          {entries.map(entry => (
            <div key={entry.id} className="bg-muted/30 border border-border rounded-lg px-4 py-3">
              <div className="flex items-start justify-between gap-2">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-0.5">
                    <span className="flex items-center gap-1 text-xs font-medium text-foreground">
                      {ROLE_ICON[entry.roleLevel ?? ''] ?? null}
                      {entry.performedBy}
                    </span>
                    <span className="text-xs text-muted-foreground">→</span>
                    <span className="text-xs text-foreground/70">{entry.targetUser}</span>
                  </div>
                  <div className="text-xs font-semibold text-primary">{entry.action}</div>
                  {entry.details && <div className="text-xs text-muted-foreground mt-0.5 truncate">{entry.details}</div>}
                </div>
                <div className="text-xs text-muted-foreground whitespace-nowrap shrink-0">{formatDate(entry.timestamp)}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { getSiteSettings, updateSiteSetting } from 'zite-endpoints-sdk';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { Settings, RefreshCw } from 'lucide-react';

const DEFAULT_SETTINGS = [
  { key: 'maintenance_mode', label: 'Maintenance Mode', description: 'Show a maintenance page to all visitors', default: 'false' },
  { key: 'new_registrations', label: 'New Registrations', description: 'Allow new users to sign up', default: 'true' },
  { key: 'game_access', label: 'Game Access', description: 'Allow users to access the games hub', default: 'true' },
  { key: 'proxy_access', label: 'Proxy Access', description: 'Allow users to access the proxy hub', default: 'true' },
  { key: 'show_announcements', label: 'Show Announcements', description: 'Display active announcements to users', default: 'true' },
];

export default function SiteControls() {
  const [values, setValues] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState<string | null>(null);

  const load = async () => {
    setLoading(true);
    try {
      const res = await getSiteSettings({});
      const map: Record<string, string> = {};
      for (const s of res.settings) {
        if (s.settingKey) map[s.settingKey] = s.settingValue ?? '';
      }
      setValues(map);
    } catch { toast.error('Failed to load settings'); }
    setLoading(false);
  };

  useEffect(() => { load(); }, []);

  const toggle = async (key: string, currentValue: string) => {
    const newVal = currentValue === 'true' ? 'false' : 'true';
    setSaving(key);
    try {
      await updateSiteSetting({ key, value: newVal });
      setValues(prev => ({ ...prev, [key]: newVal }));
      toast.success('Setting updated');
    } catch (e: any) { toast.error(e?.message ?? 'Failed to update'); }
    setSaving(null);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Settings className="w-4 h-4" /> Site-wide toggles
        </div>
        <Button variant="ghost" size="icon" onClick={load} className="h-7 w-7">
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </Button>
      </div>

      {loading ? (
        <div className="space-y-3">{[...Array(5)].map((_, i) => <div key={i} className="h-14 rounded-lg bg-muted/40 animate-pulse" />)}</div>
      ) : (
        <div className="space-y-2">
          {DEFAULT_SETTINGS.map(setting => {
            const val = values[setting.key] ?? setting.default;
            const isOn = val === 'true';
            const isSaving = saving === setting.key;
            return (
              <div key={setting.key} className="flex items-center justify-between bg-muted/30 border border-border rounded-xl px-4 py-3">
                <div>
                  <div className="text-sm font-medium text-foreground">{setting.label}</div>
                  <div className="text-xs text-muted-foreground">{setting.description}</div>
                </div>
                <button
                  onClick={() => toggle(setting.key, val)}
                  disabled={isSaving}
                  className={`relative inline-flex items-center w-11 h-6 rounded-full transition-colors focus:outline-none ${isOn ? 'bg-primary' : 'bg-border'} ${isSaving ? 'opacity-50' : ''}`}
                >
                  <span
                    className={`inline-block w-4 h-4 bg-white rounded-full shadow transition-transform ${isOn ? 'translate-x-6' : 'translate-x-1'}`}
                  />
                </button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { Link } from 'react-router-dom';
import { subjects } from '../data/subjects';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronRight, Star, BookOpen, Users } from 'lucide-react';
import { useState, useEffect, useCallback } from 'react';
import SecretHub from '../components/SecretHub';
import { useAuth } from 'zite-auth-sdk';

const SECRET_CODE = 'genizy';

export default function Home() {
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [listening, setListening] = useState(false);
  const [typed, setTyped] = useState('');
  const [hubOpen, setHubOpen] = useState(false);

  const handleBadgeClick = () => {
    setListening(true);
    setTyped('');
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (!listening) return;
    const next = (typed + e.key).slice(-SECRET_CODE.length);
    setTyped(next);
    if (next === SECRET_CODE) {
      setHubOpen(true);
      setListening(false);
      setTyped('');
    }
  }, [listening, typed]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  // Stop listening after 5 seconds of inactivity
  useEffect(() => {
    if (!listening) return;
    const timer = setTimeout(() => { setListening(false); setTyped(''); }, 5000);
    return () => clearTimeout(timer);
  }, [listening, typed]);

  useEffect(() => {
    if (!isLoading && !user) {
      loginWithRedirect({ redirectUrl: window.location.href });
    }
  }, [isLoading, user]);

  if (isLoading || !user) return null;

  return (
    <div>
      <AnimatePresence>
        {hubOpen && <SecretHub onClose={() => setHubOpen(false)} />}
      </AnimatePresence>

      {/* Hero */}
      <section className="relative overflow-hidden bg-gradient-to-br from-primary/10 via-background to-secondary/10 py-20 px-4">
        <div className="container mx-auto text-center max-w-3xl">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }}>
            <div
              onClick={handleBadgeClick}
              className="inline-flex items-center gap-2 bg-primary/10 text-primary rounded-full px-4 py-1 text-sm font-medium mb-6 cursor-default select-none"
            >
              <Star className="w-4 h-4 fill-current" />
              Free Learning for Everyone
            </div>
            <h1 className="text-5xl md:text-6xl font-extrabold text-foreground mb-4 leading-tight">
              Learn Anything,<br />
              <span className="text-primary">Anytime.</span>
            </h1>
            <p className="text-lg text-muted-foreground mb-8 max-w-xl mx-auto">
              Explore interactive lessons across 8 subjects. Build skills, earn confidence, and discover the joy of learning.
            </p>
            <div className="flex justify-center gap-8 mb-2">
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">8</div>
                <div className="text-sm text-muted-foreground">Subjects</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">32+</div>
                <div className="text-sm text-muted-foreground">Lessons</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-foreground">100%</div>
                <div className="text-sm text-muted-foreground">Free</div>
              </div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Subjects Grid */}
      <section className="container mx-auto px-4 py-16">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-foreground mb-2">Choose a Subject</h2>
          <p className="text-muted-foreground">Click any subject to start learning</p>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {subjects.map((subject, i) => (
            <motion.div
              key={subject.id}
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.07 }}
            >
              <Link to={`/subject/${subject.id}`}>
                <div className={`group rounded-2xl border-2 ${subject.borderColor} ${subject.bgColor} p-6 h-full hover:shadow-lg transition-all duration-200 hover:-translate-y-1 cursor-pointer`}>
                  <div className="text-5xl mb-4">{subject.emoji}</div>
                  <h3 className={`text-xl font-bold mb-1 ${subject.color}`}>{subject.name}</h3>
                  <p className="text-sm text-muted-foreground mb-4 leading-relaxed">{subject.tagline}</p>
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-muted-foreground flex items-center gap-1">
                      <BookOpen className="w-3 h-3" />
                      {subject.lessons.length} lessons
                    </span>
                    <ChevronRight className={`w-4 h-4 ${subject.color} group-hover:translate-x-1 transition-transform`} />
                  </div>
                </div>
              </Link>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Footer Banner */}
      <section className="bg-primary/5 border-t border-border py-12 px-4 mt-8">
        <div className="container mx-auto flex flex-col md:flex-row items-center justify-between gap-4 max-w-4xl">
          <div className="flex items-center gap-3">
            <Users className="w-8 h-8 text-primary" />
            <div>
              <div className="font-semibold text-foreground">Built for Curious Learners</div>
              <div className="text-sm text-muted-foreground">From elementary to high school — all levels welcome</div>
            </div>
          </div>
          <div className="text-sm text-muted-foreground text-center md:text-right">
            EduWorld • Free Educational Resources
          </div>
        </div>
      </section>
    </div>
  );
}

