  Banned:    { color: 'bg-destructive/20 text-destructive border-destructive/30', icon: <UserX className="w-3 h-3" /> },
};

const ASSIGNABLE_ROLES: Record<string, RoleName[]> = {
  Owner: ['Owner', 'Admin', 'Moderator', 'User', 'Banned'],
  Admin: ['Moderator', 'User', 'Banned'],
  Moderator: ['User', 'Banned'],
};

