              {initials}
            </div>
            <div className="min-w-0">
              <div className="font-semibold text-foreground text-base truncate">
                {user.firstName || user.lastName ? `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim() : '(No name set)'}
              </div>
              <div className="flex items-center gap-1 text-sm text-muted-foreground truncate">
                <Mail className="w-3 h-3 shrink-0" /> {user.email}
              </div>
              <div className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full border font-medium mt-1.5 ${meta.color}`}>
                {meta.icon} {user.role ?? 'User'}
              </div>
            </div>
          </div>

          <div className="space-y-5">
            {/* Name editing — Admin+ only */}
            {canEditName && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Edit Name</Label>
                <div className="flex gap-2">
                  <Input placeholder="First name" value={firstName} onChange={e => setFirstName(e.target.value)} className="text-sm" />
                  <Input placeholder="Last name" value={lastName} onChange={e => setLastName(e.target.value)} className="text-sm" />
                  <Button size="icon" className="shrink-0 h-9 w-9" onClick={handleSaveName} disabled={savingName}>
                    {savingName ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                  </Button>
                </div>
              </div>
            )}

            {/* Role change */}
            {canModify && assignableRoles.length > 0 && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Change Role</Label>
                <div className="flex items-center gap-2">
                  <Select value={user.role ?? 'User'} onValueChange={v => handleRoleChange(v as RoleName)} disabled={savingRole}>
                    <SelectTrigger className="text-sm flex-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      {assignableRoles.map(r => (
                        <SelectItem key={r} value={r}>
                          <div className="flex items-center gap-2">{ROLE_META[r]?.icon} {r}</div>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {savingRole && <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />}
                </div>
              </div>
            )}

            {/* Active status */}
            {canModify && (
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Account Status</Label>
                <div className="flex items-center justify-between bg-muted/30 border border-border rounded-lg px-4 py-3">
                  <div>
                    <div className="text-sm font-medium text-foreground">
                      {user.isActive !== false ? '✅ Active' : '🚫 Deactivated'}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {user.isActive !== false ? 'User can log in normally' : 'User cannot access the platform'}
                    </div>
                  </div>
                  <Button variant="outline" size="sm" onClick={handleToggleActive} disabled={savingStatus}>
                    {savingStatus
                      ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
                      : user.isActive !== false
                        ? <><Ban className="w-3.5 h-3.5 mr-1.5" />Deactivate</>
                        : <><UserCheck className="w-3.5 h-3.5 mr-1.5" />Activate</>
                    }
                  </Button>
                </div>
              </div>
            )}

            {/* Account info */}
            <div className="space-y-2">
              <Label className="text-xs text-muted-foreground font-semibold uppercase tracking-wider">Account Info</Label>
              <div className="bg-muted/30 border border-border rounded-lg divide-y divide-border text-sm">
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Calendar className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="text-muted-foreground">Joined</span>
                  <span className="font-medium text-foreground ml-auto text-xs">{fmt(user.joinedAt)}</span>
                </div>
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Clock className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <span className="text-muted-foreground">Last Active</span>
                  <span className="font-medium text-foreground ml-auto text-xs">{fmt(user.lastActive)}</span>
                </div>
                <div className="flex items-center gap-2 px-4 py-2.5">
                  <Badge variant="outline" className="text-xs">{user.id.slice(0, 8)}…</Badge>
                  <span className="text-muted-foreground text-xs">User ID</span>
                </div>
              </div>
            </div>

            {/* Delete */}
            {canDelete && (
              <Button variant="destructive" className="w-full" onClick={() => setConfirmDelete(true)} disabled={deleting}>
                {deleting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Trash2 className="w-4 h-4 mr-2" />}
                Delete User Account
              </Button>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete User</AlertDialogTitle>
            <AlertDialogDescription>
              Permanently delete <strong>{user.email}</strong>? This action cannot be undone and will remove all their data.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

