  Owner:     { color: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30', icon: <Crown className="w-3 h-3" /> },
  Admin:     { color: 'bg-primary/20 text-primary border-primary/30', icon: <Shield className="w-3 h-3" /> },
