import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

function roleRank(r?: string) {
  return r === 'Owner' ? 4 : r === 'Admin' ? 3 : r === 'Moderator' ? 2 : r === 'Banned' ? 0 : 1;
}

export default createEndpoint({
  description: 'Get user statistics — Moderator and above',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.object({
    total: z.number(),
    active: z.number(),
    inactive: z.number(),
    byRole: z.object({
      Owner: z.number(),
      Admin: z.number(),
      Moderator: z.number(),
      User: z.number(),
      Banned: z.number(),
    }),
  }),
  execute: async ({ context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    if (roleRank(caller?.role) < 2) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Insufficient permissions' });
    }
    const { records } = await Users.findAll({ limit: 2000 });
    const stats = {
      total: records.length,
      active: 0,
      inactive: 0,
      byRole: { Owner: 0, Admin: 0, Moderator: 0, User: 0, Banned: 0 },
    };
    for (const u of records) {
      if (u.isActive !== false) stats.active++;
      else stats.inactive++;
      const role = (u.role ?? 'User') as keyof typeof stats.byRole;
      if (role in stats.byRole) stats.byRole[role]++;
    }
    return stats;
  },
});

import { z } from 'zod';
import { createEndpoint, Users, AuditLog, ZiteError } from 'zite-integrations-backend-sdk';

function roleRank(r?: string) {
  return r === 'Owner' ? 4 : r === 'Admin' ? 3 : r === 'Moderator' ? 2 : r === 'Banned' ? 0 : 1;
}

export default createEndpoint({
  description: 'Bulk update users — enforces role hierarchy',
  authenticated: true,
  inputSchema: z.object({
    userIds: z.array(z.string()),
    role: z.enum(['Owner', 'Admin', 'Moderator', 'User', 'Banned']).optional(),
    isActive: z.boolean().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), updated: z.number() }),
  execute: async ({ input, context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    const callerRank = roleRank(caller?.role);

    if (callerRank < 2) throw new ZiteError({ code: 'FORBIDDEN', message: 'Insufficient permissions' });
    if (input.role && roleRank(input.role) >= callerRank) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Cannot assign a role equal to or higher than yours' });
    }
    if (callerRank === 2 && input.role && !['User', 'Banned'].includes(input.role)) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Moderators can only assign User or Banned' });
    }

    const updates: Partial<{ role: string; isActive: boolean }> = {};
    if (input.role !== undefined) updates.role = input.role;
    if (input.isActive !== undefined) updates.isActive = input.isActive;

    let updated = 0;
    for (const userId of input.userIds) {
      if (userId === context.user.id) continue;
      const target = await Users.findOne({ id: userId });
      if (!target || roleRank(target.role) >= callerRank) continue;
      await Users.update({ id: userId, record: updates });
      updated++;
    }

    const changeDesc = Object.entries(updates).map(([k, v]) => `${k}=${v}`).join(', ');
    await AuditLog.create({
      record: {
        action: `Bulk updated ${updated} users: ${changeDesc}`,
        performedBy: context.user.email,
        targetUser: `${updated} users`,
        details: `${caller?.role} ${context.user.email} bulk updated ${updated} users (${changeDesc})`,
        timestamp: new Date().toISOString(),
        roleLevel: caller?.role ?? 'User',
      },
    });

    return { success: true, updated };
  },
});

import { z } from 'zod';
import { createEndpoint, Users, ZiteError } from 'zite-integrations-backend-sdk';

function roleRank(r?: string) {
  return r === 'Owner' ? 4 : r === 'Admin' ? 3 : r === 'Moderator' ? 2 : r === 'Banned' ? 0 : 1;
}

export default createEndpoint({
  description: 'Get users with sort/pagination — Moderator and above',
  authenticated: true,
  inputSchema: z.object({
    search: z.string().optional(),
    roleFilter: z.string().optional(),
    sortBy: z.enum(['email', 'role', 'joinedAt', 'lastActive', 'firstName']).optional(),
    sortDir: z.enum(['asc', 'desc']).optional(),
    offset: z.number().optional(),
    limit: z.number().optional(),
  }),
  outputSchema: z.object({
    users: z.array(z.object({
      id: z.string(),
      email: z.string().optional(),
      firstName: z.string().optional(),
      lastName: z.string().optional(),
      role: z.string().optional(),
      joinedAt: z.string().optional(),
      lastActive: z.string().optional(),
      isActive: z.boolean().optional(),
    })),
    total: z.number(),
    hasMore: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    const caller = await Users.findOne({ id: context.user.id });
    if (roleRank(caller?.role) < 2) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Insufficient permissions' });
    }

    const { records } = await Users.findAll({ limit: 2000 });
    let filtered = records;

    if (input.search) {
      const q = input.search.toLowerCase();
      filtered = filtered.filter(u =>
        u.email?.toLowerCase().includes(q) ||
        u.firstName?.toLowerCase().includes(q) ||
        u.lastName?.toLowerCase().includes(q)
      );
    }

    if (input.roleFilter && input.roleFilter !== 'all') {
      filtered = filtered.filter(u => u.role?.toLowerCase() === input.roleFilter?.toLowerCase());
    }

    const sortBy = input.sortBy ?? 'joinedAt';
    const sortDir = input.sortDir ?? 'desc';
    filtered.sort((a, b) => {
      if (sortBy === 'role') {
        const diff = roleRank(a.role) - roleRank(b.role);
        return sortDir === 'asc' ? diff : -diff;
      }
      const aVal = String(a[sortBy as keyof typeof a] ?? '');
      const bVal = String(b[sortBy as keyof typeof b] ?? '');
      const cmp = aVal.localeCompare(bVal);
      return sortDir === 'asc' ? cmp : -cmp;
    });

    const total = filtered.length;
    const offset = input.offset ?? 0;
    const limit = input.limit ?? 25;

    return {
      users: filtered.slice(offset, offset + limit).map(u => ({
        id: u.id,
        email: u.email,
        firstName: u.firstName,
        lastName: u.lastName,
        role: u.role,
        joinedAt: u.joinedAt,
        lastActive: u.lastActive,
        isActive: u.isActive,
      })),
      total,
      hasMore: offset + limit < total,
    };
  },
});

import { z } from 'zod';
import { createEndpoint, Users, AuditLog, ZiteError } from 'zite-integrations-backend-sdk';

function roleRank(role?: string): number {
  switch (role) {
    case 'Owner': return 4;
    case 'Admin': return 3;
    case 'Moderator': return 2;
    case 'User': return 1;
    case 'Banned': return 0;
    default: return 1;
  }
}

export default createEndpoint({
  description: 'Update a user — enforces role hierarchy',
  authenticated: true,
  inputSchema: z.object({
    userId: z.string(),
    role: z.enum(['Owner', 'Admin', 'Moderator', 'User', 'Banned']).optional(),
    isActive: z.boolean().optional(),
    firstName: z.string().optional(),
    lastName: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const [caller, target] = await Promise.all([
      Users.findOne({ id: context.user.id }),
      Users.findOne({ id: input.userId }),
    ]);

    const callerRank = roleRank(caller?.role);
    const targetRank = roleRank(target?.role);
    const newRank = input.role ? roleRank(input.role) : targetRank;

    if (callerRank < 2) throw new ZiteError({ code: 'FORBIDDEN', message: 'Insufficient permissions' });
    if (input.userId === context.user.id) throw new ZiteError({ code: 'BAD_REQUEST', message: 'Cannot modify your own account' });
    if (targetRank >= callerRank) throw new ZiteError({ code: 'FORBIDDEN', message: 'Cannot modify a user with equal or higher rank' });
    if (newRank >= callerRank) throw new ZiteError({ code: 'FORBIDDEN', message: 'Cannot assign a role equal to or higher than yours' });
    if (callerRank === 2 && input.role && !['User', 'Banned'].includes(input.role)) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Moderators can only change users to User or Banned' });
    }
    if ((input.firstName !== undefined || input.lastName !== undefined) && callerRank < 3) {
      throw new ZiteError({ code: 'FORBIDDEN', message: 'Only Admins and above can edit user names' });
    }

    const updates: Partial<{ role: string; isActive: boolean; firstName: string; lastName: string }> = {};
    if (input.role !== undefined) updates.role = input.role;
    if (input.isActive !== undefined) updates.isActive = input.isActive;
    if (input.firstName !== undefined) updates.firstName = input.firstName;
    if (input.lastName !== undefined) updates.lastName = input.lastName;

    await Users.update({ id: input.userId, record: updates });

    const changes = Object.entries(updates).map(([k, v]) => `${k}=${v}`).join(', ');
    await AuditLog.create({
      record: {
        action: `Updated user: ${changes}`,
        performedBy: context.user.email,
        targetUser: target?.email ?? input.userId,
        details: `${caller?.role} ${context.user.email} updated ${target?.email}: ${changes}`,
        timestamp: new Date().toISOString(),
        roleLevel: caller?.role ?? 'User',
      },
    });

    return { success: true };
  },
});

